window.CAPX_BANK = {"bank_id": "CAP-X-TRAINER-2026-09-07", "bank_version": "1.1.0", "source_snapshot_date": "2026-09-07", "blueprint": "CAP-Expert (CAP-X) INFORMS Analytics Framework seven domains", "question_count": 115, "domain_counts": {"I": 18, "II": 20, "III": 24, "IV": 15, "V": 18, "VI": 12, "VII": 8}, "notes": "Original 100 items copied from ChatGPT CAP Exam Coach bank; 15 trainer-authored items appended. Original Drive files were not modified.", "form_size": 115, "form_domain_targets": {"I": 18, "II": 20, "III": 24, "IV": 15, "V": 18, "VI": 12, "VII": 8}, "questions": [{"question_id": "CAPX-D1-Q001", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.1.1"], "topic": "Eliciting a complete business problem statement", "section": "", "difficulty": "moderate", "stem": "A logistics executive says, 'Deploy machine learning so our deliveries stop being late.' The analytics team has not yet agreed on what late means or what decision the result will support. What is the best next step?", "correct_key": "B", "options": [{"key": "A", "text": "Select a gradient-boosted model and use its default accuracy metric.", "is_correct": false, "rationale": "This commits to a technical method before the business outcome, metric, constraints, and data feasibility are understood.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.2 JTA Domain I, Task 1: Obtain or Receive Problem Statement and Usability"}]}, {"key": "B", "text": "Interview the sponsor and operating experts to define the desired outcome, baseline and target metric, decision use, time frame, constraints, and relevant data.", "is_correct": true, "rationale": "A usable business problem statement is written in business terms and includes desired outcomes, success measures, constraints, and information gathered through persistent interviews.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.2 JTA Domain I, Task 1: Obtain or Receive Problem Statement and Usability"}]}, {"key": "C", "text": "Acquire external traffic data first and infer the objective from whatever fields are available.", "is_correct": false, "rationale": "Available data should not be allowed to define the business objective; the team first needs a clear statement and then evaluates data availability.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.2 JTA Domain I, Task 1: Obtain or Receive Problem Statement and Usability"}]}, {"key": "D", "text": "Build a dashboard of every delivery measure and ask the executive which chart looks useful.", "is_correct": false, "rationale": "A broad dashboard avoids the necessary clarification of the decision, key outcome, and target level.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.1 Task 1: Selecting the Target Problem (see also Chapter 1 )"}]}]}, {"question_id": "CAPX-D1-Q002", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.2.1"], "topic": "Stakeholder analysis", "section": "", "difficulty": "advanced", "stem": "A hospital scheduling project affects executives, nurses, physicians, patients, IT, and labor representatives. Leaders disagree sharply about whether throughput or staff workload is the primary concern. Which stakeholder-analysis approach is most effective at the outset?", "correct_key": "C", "options": [{"key": "A", "text": "Interview only the executive sponsor and treat funding authority as sufficient representation of operational needs and impacts.", "is_correct": false, "rationale": "Senior backing matters, but operational stakeholders hold time, data, and process knowledge needed for project success.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.3 JTA Domain I, Task 2: Identify Stakeholders"}]}, {"key": "B", "text": "Invite every named party to an unstructured workshop immediately and settle the conflicting priorities through a simple majority vote.", "is_correct": false, "rationale": "Joint sessions can help, but convening highly divergent groups without careful planning can intensify conflict.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.3 JTA Domain I, Task 2: Identify Stakeholders"}]}, {"key": "C", "text": "Map affected and influential parties, interview a broad range early, document their expectations and concerns, then design any joint session around the known conflicts.", "is_correct": true, "rationale": "This combines broad early outreach and documented perspectives with the caution advised when stakeholder views diverge.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.3 JTA Domain I, Task 2: Identify Stakeholders"}]}, {"key": "D", "text": "Delay interviews until a prototype exists, then ask stakeholders to react to the proposed workflow and measures.", "is_correct": false, "rationale": "Delaying outreach risks missing objections and essential operational information until costly commitments have been made.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Stakeholders"}]}]}, {"question_id": "CAPX-D1-Q003", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.2.2"], "topic": "RACI role assignment", "section": "", "difficulty": "moderate", "stem": "For a service-capacity initiative, the vice president owns the funding decision, the analytics lead performs the framing work, an operations expert supplies process knowledge, and regional managers need status updates. Which assignment best applies RACI?", "correct_key": "A", "options": [{"key": "A", "text": "Vice president Accountable; analytics lead Responsible; operations expert Consulted; regional managers Informed.", "is_correct": true, "rationale": "The assignment matches decision ownership, work execution, expert input, and status communication to the described roles.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Executive Sponsor [ 9 ]"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Domain Expert"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Stakeholders"}, {"source": "Project Management Institute, Stakeholder Management and RACI for AI Teams", "url": "https://www.pmi.org/blog/stakeholder-management-raci", "locator": "Section \"Stakeholder management and RACI at a glance,\" RACI role-definition table"}]}, {"key": "B", "text": "Vice president Responsible; analytics lead Informed; operations expert Accountable; regional managers Consulted.", "is_correct": false, "rationale": "It makes the sponsor perform the framing and shifts accountability to an adviser, contrary to the described responsibilities.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Executive Sponsor [ 9 ]"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Domain Expert"}, {"source": "Project Management Institute, Stakeholder Management and RACI for AI Teams", "url": "https://www.pmi.org/blog/stakeholder-management-raci", "locator": "Section \"Stakeholder management and RACI at a glance,\" RACI role-definition table"}]}, {"key": "C", "text": "Vice president Consulted; analytics lead Accountable; operations expert Informed; regional managers Responsible.", "is_correct": false, "rationale": "This separates authority from the funding owner and assigns daily framing work to managers who only require updates.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Executive Sponsor [ 9 ]"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Stakeholders"}, {"source": "Project Management Institute, Stakeholder Management and RACI for AI Teams", "url": "https://www.pmi.org/blog/stakeholder-management-raci", "locator": "Section \"Stakeholder management and RACI at a glance,\" RACI role-definition table"}]}, {"key": "D", "text": "All parties jointly Accountable and Responsible.", "is_correct": false, "rationale": "Shared engagement is valuable, but undifferentiated accountability obscures who owns the decision and who performs the work.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.2 Task 2: Assemble the Team (see also Chapter 3 )"}, {"source": "Project Management Institute, Stakeholder Management and RACI for AI Teams", "url": "https://www.pmi.org/blog/stakeholder-management-raci", "locator": "Section \"Stakeholder management and RACI at a glance,\" RACI role-definition table"}]}]}, {"question_id": "CAPX-D1-Q004", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.3.1"], "topic": "Making a problem analytically tractable", "section": "", "difficulty": "moderate", "stem": "A sponsor's initial statement is, 'Use analytics to eliminate customer frustration.' Which revision most improves its amenability to an analytics solution while retaining the business intent?", "correct_key": "D", "options": [{"key": "A", "text": "Specify a neural network trained on all available customer data, without defining a target outcome or operating decision.", "is_correct": false, "rationale": "This names a method but still omits the business outcome, target, decision, and constraints.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.2 JTA Domain I, Task 1: Obtain or Receive Problem Statement and Usability"}]}, {"key": "B", "text": "Promise to make every customer interaction perfect by quarter-end, leaving frustration and success otherwise undefined.", "is_correct": false, "rationale": "The absolute outcome is not operationally defined and is unlikely to be tractable or measurable.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.4 JTA Domain I, Task 3: Determine if the Problem Is Amenable to an Analytics Solution"}]}, {"key": "C", "text": "Analyze complaint themes and interesting patterns, but leave the intended action, population, and measurable benefit unspecified.", "is_correct": false, "rationale": "Pattern discovery alone does not specify the business action, success measure, or scope.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.1 Task 1: Selecting the Target Problem (see also Chapter 1 )"}]}, {"key": "D", "text": "Reduce the 30-day repeat-contact rate for billing calls from its measured baseline to an agreed target within six months, using available interaction data while maintaining service-quality safeguards.", "is_correct": true, "rationale": "The revision defines a measurable business outcome, scope, time frame, available-data basis, and an important constraint.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.2 JTA Domain I, Task 1: Obtain or Receive Problem Statement and Usability"}]}]}, {"question_id": "CAPX-D1-Q005", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.3.2"], "topic": "Analytics feasibility", "section": "", "difficulty": "advanced", "stem": "A lender wants a decision-support pilot in four weeks. The only labeled outcomes are restricted records whose approval process normally takes eight weeks, and no permitted proxy has been identified. Which issue most directly threatens feasibility?", "correct_key": "B", "options": [{"key": "A", "text": "The sponsor has not yet selected the preferred color palette and layout for pilot visualizations.", "is_correct": false, "rationale": "Presentation styling is secondary and does not determine whether the required analysis can be performed.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.4 JTA Domain I, Task 3: Determine if the Problem Is Amenable to an Analytics Solution"}]}, {"key": "B", "text": "The necessary outcome data are not accessible within the required time frame, and privacy restrictions may prevent their use.", "is_correct": true, "rationale": "Data availability, access, privacy, time, and resource limits are explicit feasibility considerations.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.4 JTA Domain I, Task 3: Determine if the Problem Is Amenable to an Analytics Solution"}]}, {"key": "C", "text": "Several modeling families appear plausible, so the team has not selected a final algorithm.", "is_correct": false, "rationale": "Multiple plausible methods can be carried forward at the framing stage; that is not itself a fatal feasibility problem.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.8 JTA Domain II, Task 1: Reformulate the Problem Statement as an Analytics Problem"}]}, {"key": "D", "text": "The operations group requests a brief weekly status report throughout the four-week pilot.", "is_correct": false, "rationale": "Communication cadence creates work but does not directly prevent access to the necessary analytic evidence.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.3 JTA Domain I, Task 2: Identify Stakeholders"}]}]}, {"question_id": "CAPX-D1-Q006", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.4.1"], "topic": "Clarifying conflicting objectives", "section": "", "difficulty": "advanced", "stem": "A draft states: 'Maximize service, eliminate overtime, cut inventory in half, and guarantee zero delays by Q2.' Operations says these goals conflict. What revision is most necessary?", "correct_key": "C", "options": [{"key": "A", "text": "Add several optimization algorithms and let the technical team choose among them after the statement is approved.", "is_correct": false, "rationale": "Method names do not resolve incompatible business outcomes or establish their priorities.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.5 JTA Domain I, Task 4: Refine the Problem Statement and Delineate Constraints"}]}, {"key": "B", "text": "Remove the numeric targets, retain all four desired outcomes, and let the team interpret success after delivery.", "is_correct": false, "rationale": "Removing targets makes success less clear instead of resolving the conflict.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.2 JTA Domain I, Task 1: Obtain or Receive Problem Statement and Usability"}]}, {"key": "C", "text": "Work with stakeholders to prioritize the outcomes, define acceptable tradeoffs and constraints, and restate measurable targets that can coexist.", "is_correct": true, "rationale": "The statement should evolve as stakeholder expectations and feasibility constraints become clearer.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.5 JTA Domain I, Task 4: Refine the Problem Statement and Delineate Constraints"}]}, {"key": "D", "text": "Keep every outcome unchanged and let the selected model determine which objectives and tradeoffs should receive priority.", "is_correct": false, "rationale": "A model cannot legitimately invent stakeholder value judgments that were never agreed upon.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.5 How Will We Know When We Have Succeeded?"}]}]}, {"question_id": "CAPX-D1-Q007", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.5.1"], "topic": "Distinguishing benefit measurement levels", "section": "", "difficulty": "moderate", "stem": "A food distributor is framing a waste-reduction project. Which option most clearly separates a model-performance measure, an organization-level result, and a broader societal result, while recognizing that effects can overlap?", "correct_key": "A", "options": [{"key": "A", "text": "Forecast error is the model-performance measure; spoilage cost is the organization-level result; discarded edible goods is the broader societal result.", "is_correct": true, "rationale": "Forecast error directly measures forecasting performance, spoilage cost is an internal financial result, and discarded edible goods captures the outward waste effect; the levels can still overlap.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}, {"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "B", "text": "Spoilage cost is the model-performance measure; forecast error is the broader societal result; discarded goods is only an internal result.", "is_correct": false, "rationale": "This reverses the most direct measurement levels: forecast error measures the forecast, while discarded edible goods is the result most directly extending beyond the organization.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}, {"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "C", "text": "Treat all three only as model-performance measures because the forecasting system contributes to each downstream result.", "is_correct": false, "rationale": "Analytics can contribute to all three, but contribution does not make an internal cost or a broader waste effect a direct measure of model performance.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}]}, {"key": "D", "text": "Treat only the monetized spoilage-cost change as a benefit and omit the forecast measure and nonmonetary waste effect.", "is_correct": false, "rationale": "The corpus recognizes value to organizations and broader society; a benefit inventory need not exclude performance measures or nonmonetary effects merely because they are not direct cost figures.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}]}]}, {"question_id": "CAPX-D1-Q008", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.5.2"], "topic": "Business cost identification", "section": "", "difficulty": "advanced", "stem": "A manufacturer is preparing the business case for a new scheduling solution. Which cost inventory is most complete?", "correct_key": "D", "options": [{"key": "A", "text": "Budget for software licenses and hosting, while treating internal labor, integration, and downstream support as existing overhead.", "is_correct": false, "rationale": "Licensing is only one possible direct cost and omits people, integration, disruption, and ongoing support.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Vendor Pricing"}]}, {"key": "B", "text": "Count model-development labor, data access, and computing, but defer user training and ongoing support to a later operating budget.", "is_correct": false, "rationale": "Technical development costs omit business-side implementation and recurring operating costs.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.4.1 Projects"}]}, {"key": "C", "text": "Count staff training, change-management effort, and early user support, but exclude data preparation, platform delivery, and continuing maintenance.", "is_correct": false, "rationale": "Adoption costs matter, but they do not capture data preparation, development, delivery infrastructure, and continuing maintenance costs.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.4.1 Projects"}]}, {"key": "D", "text": "Development and platform costs, data and integration work, staff training and process change, and ongoing maintenance and support.", "is_correct": true, "rationale": "The full case includes technical and business resources needed to build, implement, and sustain the solution.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.4.1 Projects"}]}]}, {"question_id": "CAPX-D1-Q009", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.5.3"], "topic": "Determining the current state", "section": "", "difficulty": "advanced", "stem": "A dispatch center says it has no formal scheduling process, yet experienced supervisors consistently make workable assignments. What is the best way to establish the current state?", "correct_key": "B", "options": [{"key": "A", "text": "Assume there is no process and use a standard industry workflow as the baseline.", "is_correct": false, "rationale": "Informal operating knowledge may be central; replacing it with an assumed process can erase important constraints and practices.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.3 How Will This Problem Be Solved Without a New Model?"}]}, {"key": "B", "text": "Observe the work, interview supervisors and operators, and document the rules, spreadsheets, exceptions, handoffs, and current performance measures they actually use.", "is_correct": true, "rationale": "Current-state discovery should capture tribal wisdom and actual procedures through observation and knowledgeable interviews.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.3 How Will This Problem Be Solved Without a New Model?"}]}, {"key": "C", "text": "Ask IT to describe the process from system logs alone.", "is_correct": false, "rationale": "Logs may reveal transactions but not the judgments, workarounds, or organizational taboos behind them.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.3 How Will This Problem Be Solved Without a New Model?"}]}, {"key": "D", "text": "Begin with a future-state process map so participants are not anchored to current practice.", "is_correct": false, "rationale": "A business case requires an evidence-based current-state baseline before benefits from a future state can be assessed.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}]}]}, {"question_id": "CAPX-D1-Q010", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.5.4"], "topic": "Measuring solution value", "section": "", "difficulty": "advanced", "stem": "A retailer pilots a replenishment recommendation for 20 stores. Which evaluation best measures the solution's business value?", "correct_key": "A", "options": [{"key": "A", "text": "Compare predefined business metrics over the pilot's operating period with a credible baseline, then report observed changes alongside implementation and operating costs.", "is_correct": true, "rationale": "Actual business value requires use, data collection, and analysis of core business metrics, considered alongside the resources needed to implement and operate the solution.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.21 CRISP-DM Phase 5: Evaluation"}, {"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.4.1 Projects"}]}, {"key": "B", "text": "Report strong in-sample fit and treat improvement over a simpler model as the pilot's realized financial value.", "is_correct": false, "rationale": "Training-set fit is not a valid estimate of predictive performance and, even if it were, would not establish an observed business outcome.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}, {"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}, {"key": "C", "text": "Count accepted recommendations and treat higher recommendation volume as sufficient evidence of improved inventory economics.", "is_correct": false, "rationale": "Output volume does not show that recommendations changed inventory, service, revenue, or cost.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}]}, {"key": "D", "text": "Survey the project team about whether the pilot felt successful, without comparing the agreed operational measures.", "is_correct": false, "rationale": "Team sentiment is not a substitute for the agreed business metrics and target levels in the problem statement.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.2 JTA Domain I, Task 1: Obtain or Receive Problem Statement and Usability"}]}]}, {"question_id": "CAPX-D1-Q011", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.5.5"], "topic": "Risk mitigation in the business case", "section": "", "difficulty": "advanced", "stem": "A proposed maintenance model depends on sensor histories whose completeness and access rights are uncertain. The sponsor accepts a small discovery budget but will not fund a full project without evidence. What is the best mitigation?", "correct_key": "C", "options": [{"key": "A", "text": "Promise full delivery on schedule and defer data-access and quality checks until model building is underway.", "is_correct": false, "rationale": "Committing before checking availability, quality, and access ignores core feasibility risks.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.4 JTA Domain I, Task 3: Determine if the Problem Is Amenable to an Analytics Solution"}]}, {"key": "B", "text": "Buy a larger computing environment and reserve additional storage, assuming capacity will offset incomplete or inaccessible data.", "is_correct": false, "rationale": "More compute does not repair unavailable, unauthorized, or systematically missing evidence.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "Run a time-boxed data-discovery pilot with representative extracts, access approval, quality checks, explicit go/no-go criteria, and a fallback scope.", "is_correct": true, "rationale": "The mitigation reduces uncertainty before the major commitment and directly tests the availability and quality conditions on which feasibility depends.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}, {"key": "D", "text": "Exclude the uncertainty from the business case and treat the sponsor's discovery-budget approval as sufficient risk acceptance.", "is_correct": false, "rationale": "Accepted risk still needs explicit treatment, ownership, and monitoring to support a sound decision.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.4 JTA Domain I, Task 3: Determine if the Problem Is Amenable to an Analytics Solution"}]}]}, {"question_id": "CAPX-D1-Q012", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.5.6"], "topic": "Unintended consequences", "section": "", "difficulty": "advanced", "stem": "A public-service triage concept relies heavily on smartphone activity. Community representatives warn that rural and low-income residents may be underrepresented. Which response is strongest?", "correct_key": "B", "options": [{"key": "A", "text": "Remove explicit income and location fields, then apply the same data and thresholds to every resident group.", "is_correct": false, "rationale": "Omitting protected or sensitive variables does not remove bias carried through correlated variables or unrepresentative data.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "B", "text": "Assess representativeness and group impacts, involve affected stakeholders, test alternative data and thresholds, retain human review or appeal, and monitor after launch.", "is_correct": true, "rationale": "The response addresses data bias, fairness, responsibility, auditability, and the possibility of harmful unintended effects.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "C", "text": "Optimize overall accuracy as the sole criterion, since one aggregate score treats every record consistently.", "is_correct": false, "rationale": "Aggregate accuracy can conceal discriminatory effects, and model outputs may reflect biases in data and design choices.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "D", "text": "Launch the system first, then begin an ethical review only if users file a documented complaint.", "is_correct": false, "rationale": "Responsible practice anticipates and audits for societal consequences before harm occurs.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}]}, {"question_id": "CAPX-D1-Q013", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.6.1"], "topic": "Sponsor agreement and stakeholder alignment", "section": "", "difficulty": "moderate", "stem": "The accountable finance sponsor says the draft business problem statement is full of unfamiliar statistical language and will not approve it. What should the analytics lead do?", "correct_key": "D", "options": [{"key": "A", "text": "Add formal derivations and model terminology so the sponsor can see that the technical team understands the methods.", "is_correct": false, "rationale": "More technical detail compounds the communication problem and can reduce stakeholder confidence.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.7 JTA Domain I, Task 6: Obtain Stakeholder Agreement on the Business Statement"}]}, {"key": "B", "text": "Ask a technical reviewer to approve the statement on the sponsor's behalf, then record that approval as sufficient.", "is_correct": false, "rationale": "Technical review cannot replace agreement from the accountable business stakeholder.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.7 JTA Domain I, Task 6: Obtain Stakeholder Agreement on the Business Statement"}]}, {"key": "C", "text": "Proceed with the documented analytics plan and treat the sponsor's lack of understanding as a communication issue outside approval.", "is_correct": false, "rationale": "The milestone requires stakeholder understanding and written approval, not unilateral technical completeness.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.7 JTA Domain I, Task 6: Obtain Stakeholder Agreement on the Business Statement"}]}, {"key": "D", "text": "Rewrite it in the organization's business language, foreground outcomes, metrics, constraints, and risks, walk the sponsor through it, and seek written approval.", "is_correct": true, "rationale": "A mid-level manager should readily understand the statement, and the goal is written approval from the key stakeholder.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.7 JTA Domain I, Task 6: Obtain Stakeholder Agreement on the Business Statement"}]}]}, {"question_id": "CAPX-D1-Q014", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.1.1"], "topic": "Separating a requested deliverable from the business question", "section": "", "difficulty": "advanced", "stem": "A call-center director requests 'a real-time dashboard with 40 measures.' Before accepting the dashboard as the problem definition, which question is most important?", "correct_key": "A", "options": [{"key": "A", "text": "What decision or action should the dashboard improve, for whom, and which business outcome will show that it worked?", "is_correct": true, "rationale": "The requested artifact may be a proposed solution; framing begins by clarifying the underlying objective, user, decision, and measure of success.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.4.1 Projects"}]}, {"key": "B", "text": "Which charting library and rendering framework should the technical team use for the requested real-time dashboard?", "is_correct": false, "rationale": "A tool choice does not reveal the underlying business problem or success criterion.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.2 JTA Domain I, Task 1: Obtain or Receive Problem Statement and Usability"}]}, {"key": "C", "text": "Can the dashboard display every available field and retain all 40 measures on its main page?", "is_correct": false, "rationale": "Displaying all fields increases scope without identifying which information supports a decision.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.1 Task 1: Selecting the Target Problem (see also Chapter 1 )"}]}, {"key": "D", "text": "Which competitor's dashboard design should be copied to make the proposed artifact appear familiar and modern?", "is_correct": false, "rationale": "Competitive appearance is secondary to the sponsor's own decision process and business outcome.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.2 JTA Domain I, Task 1: Obtain or Receive Problem Statement and Usability"}]}]}, {"question_id": "CAPX-D1-Q015", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.2.1", "CAP-X 1.5.5"], "topic": "Managing stakeholder conflict as a project risk", "section": "", "difficulty": "advanced", "stem": "A workforce-planning initiative has strong executive backing, but labor representatives and site managers hold sharply different views and control essential operational knowledge. What should the analytics professional do first?", "correct_key": "C", "options": [{"key": "A", "text": "Use the executive mandate to require a single joint meeting and settle the issue immediately.", "is_correct": false, "rationale": "Authority may secure attendance, but an unplanned meeting among divergent groups can worsen the situation.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.3 JTA Domain I, Task 2: Identify Stakeholders"}]}, {"key": "B", "text": "Exclude labor representatives from framing because they do not own the budget and site managers can speak for operations.", "is_correct": false, "rationale": "Affected stakeholders can surface operational constraints and may later block adoption if ignored.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Stakeholders"}]}, {"key": "C", "text": "Interview the groups separately, map interests and influence, document common ground and conflicts, then design a facilitated alignment process with the sponsor.", "is_correct": true, "rationale": "Early broad outreach captures perspectives while careful planning reduces the risk created by highly divergent views.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.3 JTA Domain I, Task 2: Identify Stakeholders"}]}, {"key": "D", "text": "Delay stakeholder engagement until preliminary model outputs provide a neutral evidence base for resolving the disputed priorities.", "is_correct": false, "rationale": "The model cannot encode legitimate operational and value tradeoffs that the team never elicited.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.5.1 Who Are the System Operator Stakeholders?"}]}]}, {"question_id": "CAPX-D1-Q016", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X 1.5.2", "CAP-X 1.5.4"], "topic": "Prioritizing analytics opportunities", "section": "", "difficulty": "advanced", "stem": "Two proposed analytics initiatives require similar teams and schedules. One has a credible potential impact of $40 million; the other has a $400,000 impact and is favored by a senior manager. Both remain feasible after an initial risk screen. What is the best business-case recommendation?", "correct_key": "B", "options": [{"key": "A", "text": "Select the senior manager's preferred initiative because visible sponsorship will simplify approval and therefore outweigh projected impact.", "is_correct": false, "rationale": "Sponsorship helps execution, but portfolio value should reflect organization-wide impact rather than rank alone.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.4.3 Organizational Capability"}]}, {"key": "B", "text": "Prioritize the higher-impact initiative, while documenting the impact assumptions, costs, feasibility, and risks used in the comparison.", "is_correct": true, "rationale": "For comparable resource needs, opportunity prioritization should favor the larger credible organizational impact, subject to transparent assumptions and constraints.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.4.3 Organizational Capability"}]}, {"key": "C", "text": "Fund both initiatives because data storage and computing are affordable, treating shared staff and change resources as flexible.", "is_correct": false, "rationale": "Team, data, change, and implementation resources remain scarce even when some technology costs are low.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "D", "text": "Use a random selection among feasible initiatives to avoid political influence and keep the portfolio process neutral.", "is_correct": false, "rationale": "Random choice discards material evidence about expected value and resource productivity.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.4.3 Organizational Capability"}]}]}, {"question_id": "CAPX-D2-Q001", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.1.1"], "topic": "Information missing from an analytics problem statement", "section": "", "difficulty": "moderate", "stem": "A health system's approved business statement is, 'Reduce avoidable 30-day readmissions without increasing care inequity.' The proposed analytics statement says only, 'Build a predictive model.' What is the most important missing content?", "correct_key": "C", "options": [{"key": "A", "text": "Specify the production platform, programming language, and deployment architecture before confirming the prediction unit or intended action.", "is_correct": false, "rationale": "Technology selection is premature at framing and does not define what the analysis must estimate or how it will support the business need.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.8 JTA Domain II, Task 1: Reformulate the Problem Statement as an Analytics Problem"}]}, {"key": "B", "text": "Require the model to meet the sponsor's business target in every operating period before the project may proceed.", "is_correct": false, "rationale": "Analytics work cannot promise success in advance; framing should define objective criteria and uncertainty.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.5 How Will We Know When We Have Succeeded?"}]}, {"key": "C", "text": "The prediction unit and horizon, candidate inputs available at decision time, intended intervention, assumptions and constraints, and analytic and business success measures.", "is_correct": true, "rationale": "Analytics framing expands the business statement with drivers, relationships, assumptions, metrics, and a high-level approach tied to use.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.8 JTA Domain II, Task 1: Reformulate the Problem Statement as an Analytics Problem"}]}, {"key": "D", "text": "List every classification algorithm the team could try, ranked by published benchmark accuracy, before clarifying the intervention.", "is_correct": false, "rationale": "A useful frame carries a range of plausible approaches, not an indiscriminate catalog, and avoids premature specificity.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.8 JTA Domain II, Task 1: Reformulate the Problem Statement as an Analytics Problem"}]}]}, {"question_id": "CAPX-D2-Q002", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.1.2"], "topic": "Obtaining information for translation", "section": "", "difficulty": "advanced", "stem": "A manufacturer wants fewer unplanned shutdowns. The analytics team understands the financial impact but not how operators define a failure event or when they can act. What should the team do before finalizing the analytics problem?", "correct_key": "B", "options": [{"key": "A", "text": "Adopt an industry-standard failure taxonomy, map existing codes to it, and proceed without validating the definition with operators.", "is_correct": false, "rationale": "A generic definition may not match the sponsor's process, decision window, or recorded outcomes.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}, {"key": "B", "text": "Interview operators and maintenance experts, inspect data definitions and samples with owners, and document the actionable horizon, candidate drivers, outcome label, constraints, and success measures.", "is_correct": true, "rationale": "Translation requires business-expert interaction plus initial data understanding to formulate drivers, outputs, and an operationally useful problem.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.8 JTA Domain II, Task 1: Reformulate the Problem Statement as an Analytics Problem"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "C", "text": "Wait for the complete production extract, then infer the failure label, horizon, and candidate drivers statistically from observed associations.", "is_correct": false, "rationale": "Framing occurs before complete data analysis and still requires stakeholder knowledge and communication.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.8 JTA Domain II, Task 1: Reformulate the Problem Statement as an Analytics Problem"}]}, {"key": "D", "text": "Select the highest-accuracy published maintenance model, request its prescribed variables, and use its default failure horizon.", "is_correct": false, "rationale": "A prior method cannot substitute for obtaining organization-specific definitions, availability, and decision requirements.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.8 JTA Domain II, Task 1: Reformulate the Problem Statement as an Analytics Problem"}]}]}, {"question_id": "CAPX-D2-Q003", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.1.3"], "topic": "Selecting a client-centered analytics problem statement", "section": "", "difficulty": "advanced", "stem": "A retention team can contact only 2,000 subscribers each week and wants to reduce preventable cancellations over the next quarter. Which analytics problem statement best supports client success?", "correct_key": "D", "options": [{"key": "A", "text": "Cluster active subscribers with the newest algorithm, then ask marketing to interpret the segments and choose weekly outreach recipients.", "is_correct": false, "rationale": "Clustering neither defines the cancellation outcome nor links results to the constrained outreach decision.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.8 JTA Domain II, Task 1: Reformulate the Problem Statement as an Analytics Problem"}]}, {"key": "B", "text": "Maximize historical cancellation accuracy and send the 2,000 highest scores to outreach without defining preventability or intervention value.", "is_correct": false, "rationale": "The ranking respects the weekly capacity, but historical accuracy alone does not define preventability, the prediction horizon, or incremental retention value.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.11 JTA Domain II, Task 4: Define the Key Metrics of Success"}]}, {"key": "C", "text": "Identify every variable correlated with cancellation and deliver a ranked-driver report, leaving outreach selection and evaluation to users.", "is_correct": false, "rationale": "An exhaustive correlation exercise does not define an actionable output or a measure of client success.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "D", "text": "Estimate each active subscriber's probability of preventable cancellation within 30 days using information available before weekly outreach, rank eligible subscribers for the 2,000 contacts, and evaluate incremental retained subscriptions and contact cost.", "is_correct": true, "rationale": "This statement connects inputs, output, decision capacity, timing, and business evaluation without prematurely fixing a specific algorithm.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.8 JTA Domain II, Task 1: Reformulate the Problem Statement as an Analytics Problem"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}]}, {"question_id": "CAPX-D2-Q004", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.2.1"], "topic": "Appropriateness of inputs and outputs", "section": "", "difficulty": "advanced", "stem": "A retailer is framing a model to predict tomorrow's stockouts before tonight's replenishment order. Which proposed input-output design is most appropriate?", "correct_key": "A", "options": [{"key": "A", "text": "Inputs: inventory, open orders, recent demand and known promotions as of order time; output: probability of a stockout tomorrow.", "is_correct": true, "rationale": "All inputs are available when the decision is made, and the output directly represents the future event the action is intended to prevent.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "B", "text": "Inputs: tomorrow's closing inventory and lost sales after business close; output: tomorrow's stockout status for tonight's replenishment order.", "is_correct": false, "rationale": "The inputs reveal information that exists only after the prediction horizon and therefore cannot support the intended decision.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "C", "text": "Inputs: store name and region; output: total annual corporate profit, used to rank tonight's replenishment actions.", "is_correct": false, "rationale": "The proposed input is insufficient and the output is too remote from the daily replenishment decision.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "D", "text": "Inputs: every warehouse field available at any time; output: an unspecified anomaly score for each store-day.", "is_correct": false, "rationale": "Unprioritized fields and an undefined output do not articulate the drivers-to-decision relationship.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}]}, {"question_id": "CAPX-D2-Q005", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.2.2"], "topic": "Drivers and their relationship to outputs", "section": "", "difficulty": "moderate", "stem": "A procurement group wants to estimate supplier delivery delay in days at purchase-order creation. Which candidate is best described as a legitimate driver rather than an output or a post-outcome artifact?", "correct_key": "B", "options": [{"key": "A", "text": "Actual receipt date for the same order.", "is_correct": false, "rationale": "Actual receipt date determines the realized output and is unavailable at order creation.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "B", "text": "The supplier's historical lead-time variability measured before the new order.", "is_correct": true, "rationale": "It is known at decision time and has a plausible relationship to future delivery delay.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "C", "text": "A flag entered after a late order is escalated.", "is_correct": false, "rationale": "The escalation flag is a consequence of lateness and would leak outcome information.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "D", "text": "The model's predicted delay for that order.", "is_correct": false, "rationale": "This is the model output, not an independent driver used to produce it.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}]}, {"question_id": "CAPX-D2-Q006", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.3.1"], "topic": "Explicit and implicit assumptions", "section": "", "difficulty": "advanced", "stem": "A demand-forecasting frame uses three years of sales recorded under stable pricing. The business plans a major pricing-policy change next month, but the draft does not mention it. Which action is best?", "correct_key": "C", "options": [{"key": "A", "text": "Treat the pricing-policy change as irrelevant because price is an input rather than the forecast output, retaining the original assumptions.", "is_correct": false, "rationale": "A changed demand-generating process can violate the implicit assumption that future behavior resembles the past.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.10 JTA Domain II, Task 3: State the Set of Assumptions Related to the Problem"}]}, {"key": "B", "text": "Discard observations from before the policy change and issue judgment-based forecasts until enough new-regime data accumulate.", "is_correct": false, "rationale": "Discarding evidence does not resolve the need to state and test assumptions about the changed environment.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.10 JTA Domain II, Task 3: State the Set of Assumptions Related to the Problem"}]}, {"key": "C", "text": "Make the stability assumption explicit, explain how the pricing change could invalidate it, and agree how it will be revisited when post-change data become available.", "is_correct": true, "rationale": "The frame should communicate the accessible assumption that future patterns resemble the past and make clear why the planned change puts that assumption at risk.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.10 JTA Domain II, Task 3: State the Set of Assumptions Related to the Problem"}]}, {"key": "D", "text": "Keep the historical stability assumption implicit and disclose the policy change only if the deployed forecast later misses targets.", "is_correct": false, "rationale": "Assumptions and accessible risks belong in the framing document before approval.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.10 JTA Domain II, Task 3: State the Set of Assumptions Related to the Problem"}]}]}, {"question_id": "CAPX-D2-Q007", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.3.2"], "topic": "Impact of unmet assumptions", "section": "", "difficulty": "advanced", "stem": "A fraud model was framed under the assumption that transaction behavior would remain stable. A new payment channel changes customer and attacker behavior before launch. What is the strongest conclusion?", "correct_key": "A", "options": [{"key": "A", "text": "The historical relationship may no longer hold, so expected error rates and business impact are unreliable; the team should revisit data, validation, thresholds, and possibly the problem frame.", "is_correct": true, "rationale": "When a core assumption fails, the model approach and promised outcomes may no longer be appropriate and require revision.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.10 JTA Domain II, Task 3: State the Set of Assumptions Related to the Problem"}]}, {"key": "B", "text": "Keep the approved frame because stability matters only after launch, when monitoring can detect any new-channel error.", "is_correct": false, "rationale": "The changed process affects the evidence used to justify the solution before deployment.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.10 JTA Domain II, Task 3: State the Set of Assumptions Related to the Problem"}]}, {"key": "C", "text": "Add more transactions from the prior payment channel until the historical sample is large enough to restore validity.", "is_correct": false, "rationale": "Additional data from the old regime do not represent the new channel's behavior.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "D", "text": "Preserve the original success target and launch schedule, but stop reporting the metric until enough new-channel data accumulate.", "is_correct": false, "rationale": "Undefined or shifting evaluation undermines the agreed criteria for success.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.5 How Will We Know When We Have Succeeded?"}]}]}, {"question_id": "CAPX-D2-Q008", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.3.3"], "topic": "Constraints in analytics framing", "section": "", "difficulty": "moderate", "stem": "A municipal inspection model must produce recommendations within two seconds, cannot use protected attributes, must fit the existing staffing capacity, and has a fixed implementation budget. How should these conditions appear in the analytics problem statement?", "correct_key": "D", "options": [{"key": "A", "text": "Omit all four conditions from the formal statement so analysts can compare methods before constraining solution design.", "is_correct": false, "rationale": "Ignoring operational, ethical, technical, and resource limits can produce a solution that cannot be used.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.4 JTA Domain I, Task 3: Determine if the Problem Is Amenable to an Analytics Solution"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.5 JTA Domain I, Task 4: Refine the Problem Statement and Delineate Constraints"}]}, {"key": "B", "text": "Record response time and budget as the only formal constraints, treating staffing and permitted-use restrictions as later deployment details.", "is_correct": false, "rationale": "The staffing, permitted-use, and budget limits also shape the feasible solution.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.4 JTA Domain I, Task 3: Determine if the Problem Is Amenable to an Analytics Solution"}]}, {"key": "C", "text": "List the conditions as preferences to revisit after model selection, when their tradeoffs can be estimated more precisely.", "is_correct": false, "rationale": "Known constraints should be made explicit during framing so stakeholders approve a realistic plan.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.4 What Modeling Technique Will Be Used?"}]}, {"key": "D", "text": "Document all four as explicit constraints, explain how each limits data, methods, or deployment choices, and confirm stakeholder agreement on the resulting tradeoffs.", "is_correct": true, "rationale": "Known technical, ethical, operational, and resource constraints should shape a realistic analytic approach and be explicit when stakeholders agree to the frame.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.4 JTA Domain I, Task 3: Determine if the Problem Is Amenable to an Analytics Solution"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.5 JTA Domain I, Task 4: Refine the Problem Statement and Delineate Constraints"}]}]}, {"question_id": "CAPX-D2-Q009", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.3.4"], "topic": "Limitations relative to the business problem", "section": "", "difficulty": "advanced", "stem": "A telecom team can predict voluntary churn accurately but has no evidence about which retention offer will work, and the call center can contact only a fraction of flagged customers. What limitation should be stated?", "correct_key": "B", "options": [{"key": "A", "text": "Use the risk ranking as the complete solution and let campaign staff choose offers without testing treatment effects or capacity constraints.", "is_correct": false, "rationale": "Prediction identifies risk but does not establish treatment effectiveness or overcome execution capacity.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "B", "text": "The solution can prioritize likely churners but cannot by itself determine causal offer effectiveness or guarantee that limited outreach capacity will produce the desired retention benefit.", "is_correct": true, "rationale": "The statement accurately bounds what the output supports and distinguishes prediction from the broader business intervention.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.11 JTA Domain II, Task 4: Define the Key Metrics of Success"}]}, {"key": "C", "text": "Limit the caveat to risk-score uncertainty, treating offer design and outreach capacity as operational issues outside the analytics frame.", "is_correct": false, "rationale": "Score uncertainty is relevant, but the frame must also state that prediction does not establish offer effectiveness or overcome the limited outreach capacity.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}, {"key": "D", "text": "Recommend the historically most common retention offer to every high-risk subscriber, assuming past uptake establishes treatment effectiveness.", "is_correct": false, "rationale": "Historical offer frequency does not show which intervention produces incremental retention for a selected subscriber, so this still overstates what the prediction supports.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.9 JTA Domain II, Task 2: Develop a Proposed Set of Drivers and Relationships to Outputs"}]}]}, {"question_id": "CAPX-D2-Q010", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.4.1"], "topic": "Tradeoffs among success measures", "section": "", "difficulty": "advanced", "stem": "A fraud-screening model can catch more fraud only by reviewing more legitimate transactions. Missed fraud is costly, but false alerts create customer friction and investigator workload. How should the primary measure be framed?", "correct_key": "C", "options": [{"key": "A", "text": "Choose the threshold that maximizes overall validation accuracy, then monitor only the fraction of correctly classified transactions.", "is_correct": false, "rationale": "Overall accuracy can conceal performance on rare positives and ignores asymmetric business consequences.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.2 Classification Performance Evaluation"}]}, {"key": "B", "text": "Choose the threshold that maximizes recall while allowing the review queue to absorb any resulting false alerts later.", "is_correct": false, "rationale": "Recall captures missed fraud but ignores review capacity and customer harm from false positives.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.2 Classification Performance Evaluation"}]}, {"key": "C", "text": "Define an agreed business-value or loss measure combining missed-fraud cost, false-alert cost and capacity, then choose and monitor the threshold with its recall/false-positive tradeoff.", "is_correct": true, "rationale": "Classification thresholds create an explicit tradeoff, and real-world asymmetric costs can be translated into a business-case statistic.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.2 Classification Performance Evaluation"}]}, {"key": "D", "text": "Use a 50% cutoff as the neutral operating point, adjusting it only if overall accuracy later declines.", "is_correct": false, "rationale": "Appropriate thresholds vary by prevalence, costs, and the intended operating point.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.2 Classification Performance Evaluation"}]}]}, {"question_id": "CAPX-D2-Q011", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.4.2"], "topic": "Verifying measures of success", "section": "", "difficulty": "advanced", "stem": "Before a routing pilot starts, stakeholders agree that the solution should reduce average delivery time without increasing cost or missed-delivery rates. Which verification plan is strongest?", "correct_key": "A", "options": [{"key": "A", "text": "Predefine each metric, target, measurement window, and required data; compare observed pilot results with the pre-pilot baseline and report whether the agreed targets were met.", "is_correct": true, "rationale": "Success metrics and goals should be defined clearly in advance, supported by available data, and evaluated using results observed after the solution is put into use.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.11 JTA Domain II, Task 4: Define the Key Metrics of Success"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.21 CRISP-DM Phase 5: Evaluation"}]}, {"key": "B", "text": "Select the metric and target after reviewing pilot results so the team can emphasize the outcome with the clearest improvement.", "is_correct": false, "rationale": "Post hoc metric selection creates shifting goals and undermines credible verification.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.5 How Will We Know When We Have Succeeded?"}]}, {"key": "C", "text": "Verify solver feasibility and runtime against technical criteria, treating delivery, cost, and service outcomes as later operational measures.", "is_correct": false, "rationale": "Technical feasibility does not establish the agreed delivery-time, cost, and service outcomes.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.11 JTA Domain II, Task 4: Define the Key Metrics of Success"}]}, {"key": "D", "text": "Use the sponsor's end-of-pilot assessment as the decision rule, supplemented by a summary of selected favorable metrics.", "is_correct": false, "rationale": "Stakeholder judgment matters, but it should be informed by the predefined measurable criteria.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.2.5 How Will We Know When We Have Succeeded?"}]}]}, {"question_id": "CAPX-D2-Q012", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.5.1"], "topic": "Baseline performance and problem prioritization", "section": "", "difficulty": "advanced", "stem": "A fulfillment baseline study finds that 68% of late orders arise from stock-location errors, 20% from carrier delays, and 12% from other causes. The organization can change only internal warehouse processes this quarter. Which analytics problem should be prioritized?", "correct_key": "D", "options": [{"key": "A", "text": "Predict short-term international fuel-price movements and use them to renegotiate carrier surcharges during the warehouse pilot.", "is_correct": false, "rationale": "The proposed output is remote from the dominant, controllable baseline source of late orders.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}]}, {"key": "B", "text": "Optimize carrier assignments and contract terms to address carrier-related delays despite the current freeze on contract changes.", "is_correct": false, "rationale": "It targets a smaller contributor that is not actionable within the stated horizon.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.4 JTA Domain I, Task 3: Determine if the Problem Is Amenable to an Analytics Solution"}]}, {"key": "C", "text": "Build a warehouse dashboard covering inventory, labor, carrier, and fuel measures before selecting a specific intervention.", "is_correct": false, "rationale": "A broad dashboard does not focus on the baseline factor with the greatest controllable impact.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.1 Task 1: Selecting the Target Problem (see also Chapter 1 )"}]}, {"key": "D", "text": "Identify and predict stock-location errors early enough for correction, with success measured by their contribution to late orders and warehouse cost.", "is_correct": true, "rationale": "It targets the largest controllable baseline driver and ties the analytic output to business performance.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.6 JTA Domain I, Task 5: Define an Initial Set of Business Benefits"}]}]}, {"question_id": "CAPX-D2-Q013", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.6.1"], "topic": "Implementation risk mitigation", "section": "", "difficulty": "advanced", "stem": "A customer analytics project depends on three data owners, one of whom has not confirmed access. Missing the access date would invalidate the launch schedule. What is the most effective framing-stage mitigation?", "correct_key": "B", "options": [{"key": "A", "text": "Treat sponsor support as sufficient approval and leave the unresolved owner-access dependency outside the launch plan.", "is_correct": false, "rationale": "Executive support helps but data-owner resistance and approval steps can still cause substantial delay.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.15 JTA Domain III, Task 2: Acquire Data"}]}, {"key": "B", "text": "Engage the data owner now, verify access and inspect a representative extract before committing to the method, and document how failure would alter scope or schedule.", "is_correct": true, "rationale": "Data feasibility depends on owner cooperation, actual access, and understanding the source; documenting the consequence of failure keeps the frame realistic.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}, {"key": "C", "text": "Add schedule buffer for possible approval delay, but do not contact the data owner or verify a representative extract.", "is_correct": false, "rationale": "Buffer alone neither reduces the probability of the access failure nor establishes a usable fallback.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.15 JTA Domain III, Task 2: Acquire Data"}]}, {"key": "D", "text": "Start model engineering on synthetic data and preserve the original launch date without confirming permission, availability, or fitness.", "is_correct": false, "rationale": "Synthetic development may help engineering, but it cannot prove real-data availability, fitness, or permission.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.14 JTA Domain III, Task 1: Identify and Prioritize Data Needs and Sources"}]}]}, {"question_id": "CAPX-D2-Q014", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.6.2"], "topic": "Ethical risk mitigation", "section": "", "difficulty": "advanced", "stem": "A credit-risk prototype excludes race, but review shows that several inputs are strong proxies and error rates differ materially across groups. What is the best mitigation approach?", "correct_key": "C", "options": [{"key": "A", "text": "Exclude the protected attribute, retrain the model, and proceed if aggregate accuracy and overall approval rates remain within target.", "is_correct": false, "rationale": "Correlated variables can still create discriminatory outcomes even when a protected field is omitted.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "B", "text": "Optimize and publish aggregate accuracy using one threshold for all applicants, without evaluating subgroup outcomes.", "is_correct": false, "rationale": "Overall performance can hide disparate effects and does not satisfy fairness or auditability concerns.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "C", "text": "Investigate proxy effects and data representativeness, evaluate subgroup harms and alternatives, use independent review, define human accountability and appeal, and monitor fairness after deployment.", "is_correct": true, "rationale": "The approach applies responsibility, explainability, accuracy, auditability, and fairness to the observed risk.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "D", "text": "Remove every predictor correlated with a protected attribute, then deploy if the reduced model retains acceptable overall accuracy.", "is_correct": false, "rationale": "Blind deletion may destroy validity and still miss structural bias; mitigation requires evidence-based assessment and oversight.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}]}, {"question_id": "CAPX-D2-Q015", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.6.3"], "topic": "Generative AI risk in an analytics solution", "section": "", "difficulty": "advanced", "stem": "A safety team proposes using a generative model to turn confidential incident records into recommended corrective actions. The text can sound authoritative even when unsupported. Which risk treatment is most appropriate in the problem frame?", "correct_key": "A", "options": [{"key": "A", "text": "Restrict sensitive data to approved uses, ground outputs in reviewed sources, test for confabulation and harmful bias, record incidents, and require qualified human review before corrective action.", "is_correct": true, "rationale": "These controls address the scenario's privacy, confidently false content, harmful-bias, traceability, testing, incident-learning, and human-oversight risks before a consequential recommendation is acted upon.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "NIST AI 600-1, Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile", "url": "https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf", "locator": "Section 2, risk items 2, 4, 6, and 7, printed p. 4; Section 3, GV-1.6-003, printed p. 16; MP-2.2-001 and MP-2.3-001 through MP-2.3-003, printed pp. 24-25; MS-2.3-002 through MS-2.3-003 and MS-2.5-003, printed pp. 30-31"}]}, {"key": "B", "text": "Permit automatic action when a response is fluent, cites an incident number, and exceeds a confidence threshold set during testing.", "is_correct": false, "rationale": "Fluency, self-reported confidence, and an apparent citation do not establish factual accuracy; confabulation and over-reliance still require source verification and accountable human oversight.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "NIST AI 600-1, Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile", "url": "https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf", "locator": "Section 2, risk items 2 and 7, printed p. 4; Section 3, GV-1.6-003, printed p. 16; MP-2.3-001, printed p. 24; and MS-2.5-003, printed p. 31"}]}, {"key": "C", "text": "Load the complete incident archive under existing staff-access rules to maximize context, even when some records lack approved use for this model.", "is_correct": false, "rationale": "Existing staff access does not authorize every new model use; confidential records still require explicit collection, retention, protection, and permitted-use controls.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "NIST AI 600-1, Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile", "url": "https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf", "locator": "Section 2, risk item 4, printed p. 4; Section 3, MP-4.1-005 through MP-4.1-006, printed p. 26"}]}, {"key": "D", "text": "Evaluate retrieval accuracy but postpone testing generated recommendations until after rollout, because open-ended wording makes organization-specific predeployment benchmarks difficult.", "is_correct": false, "rationale": "Open-ended output does not justify postponement: capability claims and consequential recommendations still require documented, context-relevant predeployment evaluation and source verification.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "CH Appendix PDF", "url": "https://drive.google.com/file/d/1FrFXNTJZ66-yQeXY3bpGIhz5Tm9zPo2l/view", "locator": "Section 3, MS-2.3-002 through MS-2.3-003, printed p. 30; Appendix A.1.4, Pre-Deployment Testing, printed pp. 48-49"}]}]}, {"question_id": "CAPX-D2-Q016", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.7.1"], "topic": "Role-specific stakeholder alignment", "section": "", "difficulty": "moderate", "stem": "The analytics lead has drafted a demand-planning frame. The sponsor is Accountable, the analytics lead is Responsible, planners are Consulted, and store managers are Informed. Which engagement plan best fits those roles?", "correct_key": "B", "options": [{"key": "A", "text": "Have store managers approve local scope changes because they execute the plan, while the sponsor receives a summary afterward.", "is_correct": false, "rationale": "Informed users need communication, but accountability for approval remains with the sponsor.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Executive Sponsor [ 9 ]"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Stakeholders"}, {"source": "Project Management Institute, Stakeholder Management and RACI for AI Teams", "url": "https://www.pmi.org/blog/stakeholder-management-raci", "locator": "Section \"Stakeholder management and RACI at a glance,\" RACI role-definition table"}]}, {"key": "B", "text": "Have the analytics lead revise the draft using planner input, present decisions and risks to the sponsor for approval, and send store managers a clear summary and cadence of updates.", "is_correct": true, "rationale": "The plan tailors participation to work responsibility, consultation, accountability, and information needs.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Executive Sponsor [ 9 ]"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Domain Expert"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Stakeholders"}, {"source": "Project Management Institute, Stakeholder Management and RACI for AI Teams", "url": "https://www.pmi.org/blog/stakeholder-management-raci", "locator": "Section \"Stakeholder management and RACI at a glance,\" RACI role-definition table"}]}, {"key": "C", "text": "Let planners make final scope decisions because their domain expertise best positions them to judge operational feasibility.", "is_correct": false, "rationale": "Domain expertise supports consultation but does not transfer business accountability automatically.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Executive Sponsor [ 9 ]"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Domain Expert"}, {"source": "Project Management Institute, Stakeholder Management and RACI for AI Teams", "url": "https://www.pmi.org/blog/stakeholder-management-raci", "locator": "Section \"Stakeholder management and RACI at a glance,\" RACI role-definition table"}]}, {"key": "D", "text": "Send one detailed technical document to every party and request comments using the same update cadence for all roles.", "is_correct": false, "rationale": "Different stakeholders have different responsibilities and communication needs; alignment requires understandable interaction.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.12 JTA Domain II, Task 5: Obtain Stakeholder Agreement"}]}]}, {"question_id": "CAPX-D2-Q017", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X 2.7.2"], "topic": "Complete communication and sustainability expectations", "section": "", "difficulty": "advanced", "stem": "A sponsor is ready to approve an analytics frame that describes the model output and launch date but says nothing about iterative refinement, ongoing data needs, or maintenance. What should the analytics professional do?", "correct_key": "D", "options": [{"key": "A", "text": "Approve the frame unchanged and defer monitoring, maintenance, and iteration planning to the postdeployment team after launch.", "is_correct": false, "rationale": "Framing-stage alignment should set expectations for iteration and maintenance so they are not surprises later.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.12 JTA Domain II, Task 5: Obtain Stakeholder Agreement"}]}, {"key": "B", "text": "Add a general results-may-vary disclaimer and state that resource needs will be determined after the first production cycle.", "is_correct": false, "rationale": "A generic disclaimer does not explain likely iteration, continuing data dependencies, ownership, or sustainability requirements.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.12 JTA Domain II, Task 5: Obtain Stakeholder Agreement"}]}, {"key": "C", "text": "Replace the business summary with a mathematical specification so future model changes can be assessed against fixed equations.", "is_correct": false, "rationale": "Stakeholders need sufficient analytic detail for confirmation, but the document must remain understandable and outcome-centered.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.12 JTA Domain II, Task 5: Obtain Stakeholder Agreement"}]}, {"key": "D", "text": "Add assumptions, success measures, anticipated model/data iteration, maintenance and monitoring needs, resource implications, and future concerns; discuss them and obtain explicit support.", "is_correct": true, "rationale": "Complete alignment covers outcomes and the process of creating, maintaining, and sustaining the solution.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.12 JTA Domain II, Task 5: Obtain Stakeholder Agreement"}]}]}, {"question_id": "CAPX-D3-Q001", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.1.1"], "topic": "Prioritizing data needs and acquisition sequence", "section": "", "difficulty": "advanced", "stem": "A parcel carrier wants an eight-week pilot predicting missed delivery windows. Internal scan and route data are accessible now; detailed weather data need a two-week agreement; a costly national consumer file has only speculative relevance. What is the best acquisition sequence?", "correct_key": "C", "options": [{"key": "A", "text": "Buy the consumer file first because its many columns may reveal demand drivers unavailable in scan and route data.", "is_correct": false, "rationale": "Column count is not a value criterion, and speculative relevance does not justify delaying the core data.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "B", "text": "Acquire scan, route, weather, and consumer sources in parallel before inspection so the pilot cannot overlook a useful predictor.", "is_correct": false, "rationale": "Collecting all possible data consumes nontrivial resources and can undermine the focused pilot.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "Start with the accessible scan and route data needed for the output, pursue weather data in parallel because it is plausibly relevant, and defer the consumer file until evidence shows a gap it can fill.", "is_correct": true, "rationale": "The sequence prioritizes required, valuable, and available data while documenting source, transfer, and timing considerations.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.14 JTA Domain III, Task 1: Identify and Prioritize Data Needs and Sources"}]}, {"key": "D", "text": "Wait until both external agreements are complete, then document one acquisition plan covering all sources, dependencies, cost, delivery timing, and risks.", "is_correct": false, "rationale": "The data-needs plan should precede acquisition and identify required items, sources, forms, and time frames.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.14 JTA Domain III, Task 1: Identify and Prioritize Data Needs and Sources"}]}]}, {"question_id": "CAPX-D3-Q002", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.1.2"], "topic": "Resolving conflicting data requirements", "section": "", "difficulty": "advanced", "stem": "Merchandising wants daily item-level forecasts, but the approved source provides only monthly regional totals. The data owner cannot deliver finer data this quarter. What should the analytics professional communicate?", "correct_key": "A", "options": [{"key": "A", "text": "Document the mismatch and its effect on the requested output, present feasible alternatives such as a coarser forecast or new collection, identify schedule and cost tradeoffs, and obtain a prioritized decision from accountable stakeholders.", "is_correct": true, "rationale": "Clear data requirements include items, source, form, and timing; ownership and acquisition constraints must be surfaced for stakeholder prioritization.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.14 JTA Domain III, Task 1: Identify and Prioritize Data Needs and Sources"}]}, {"key": "B", "text": "Preserve the item-level promise by allocating monthly regional totals across items using recent sales shares without additional evidence or validation.", "is_correct": false, "rationale": "Aggregated data cannot legitimately be disaggregated without additional evidence, so this would create unsupported detail.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "Quietly redefine the deliverable as monthly regional forecasts and retain the original approval record to avoid schedule delay.", "is_correct": false, "rationale": "Changing scope without stakeholder alignment breaks the relationship between the data plan and approved problem.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.14 JTA Domain III, Task 1: Identify and Prioritize Data Needs and Sources"}]}, {"key": "D", "text": "Escalate the mismatch immediately to the chief executive without first assessing the schedule, cost, and output implications of alternatives.", "is_correct": false, "rationale": "Senior involvement can be necessary, but the team should first make the requirement, limitation, and decision tradeoff explicit.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.14 JTA Domain III, Task 1: Identify and Prioritize Data Needs and Sources"}]}]}, {"question_id": "CAPX-D3-Q003", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.2.1"], "topic": "Using metadata and context to choose a course of action", "section": "", "difficulty": "advanced", "stem": "Two service systems both contain a field named 'closed_date.' In one system it means work completion; in the other it means financial settlement. The proposed merge treats them as equivalent. What is the best response?", "correct_key": "D", "options": [{"key": "A", "text": "Merge the fields because their names and data types match, reconciling discrepancies only if modeling later reveals them.", "is_correct": false, "rationale": "Technical names do not establish semantic equivalence across business processes.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}, {"key": "B", "text": "Convert both timestamps to one format and time zone, then treat them as the same event without confirming definitions.", "is_correct": false, "rationale": "A common format does not resolve the conflicting definitions or time events represented.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.16 JTA Domain III, Task 3: Harmonize, Rescale, Clean, and Share Data"}]}, {"key": "C", "text": "Drop both fields and use neighboring timestamps as proxies, without first assessing their information value.", "is_correct": false, "rationale": "Discarding potentially important evidence without impact analysis may make the analytic output less useful.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "D", "text": "Use metadata and process-owner interviews to document origin and business meaning, keep the events separate or derive a defined canonical measure, and negotiate upstream definition changes if recurring integration requires them.", "is_correct": true, "rationale": "Metadata should connect technical structures to the generating business process; harmonization then preserves or reconciles distinct meanings explicitly.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}]}, {"question_id": "CAPX-D3-Q004", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.2.2"], "topic": "Data roles and governance deconfliction", "section": "", "difficulty": "moderate", "stem": "A project team, a data steward, and a governance council all claim authority to change the definition of 'active customer.' Which operating model best deconflicts the roles?", "correct_key": "B", "options": [{"key": "A", "text": "Let the project analyst revise the definition when validation improves, then publish the change after the current model is delivered.", "is_correct": false, "rationale": "Project needs do not justify unilateral changes to shared data meaning.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}, {"key": "B", "text": "Have the steward monitor quality and propose evidence-based changes, require the governance body to approve structural or definitional changes, and have the project team consume the approved definition while documenting any project-specific derivation.", "is_correct": true, "rationale": "Data stewards maintain quality, and changes to shared structures should follow governance approval with documented metadata.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}, {"key": "C", "text": "Require every data consumer to approve each definition change jointly, with the steward coordinating votes but holding no authority.", "is_correct": false, "rationale": "Diffuse responsibility obscures who monitors quality and who has authority to approve changes.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}, {"key": "D", "text": "Freeze the definition for the project and address inconsistencies through undocumented project-specific transformations outside governance records.", "is_correct": false, "rationale": "Freezing the shared definition while hiding local transformations bypasses the managed master-data lifecycle and the metadata needed to keep definitions usable.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}]}, {"question_id": "CAPX-D3-Q005", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.2.3"], "topic": "Obtaining missing data", "section": "", "difficulty": "advanced", "stem": "Field-inspection records are missing asset IDs, but each record has a timestamp and crew identifier; a master asset list contains coordinates, and crew-location logs are available. What is the best first recovery approach?", "correct_key": "C", "options": [{"key": "A", "text": "Impute each missing ID with the most common asset in that crew's territory, without validating record-level matches.", "is_correct": false, "rationale": "Frequency-based assignment can create false asset identities and corrupt relationships because it does not use the available record-level linkage evidence.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "B", "text": "Remove incomplete inspections after measuring their share, but do not test whether missingness varies by crew, asset, or location.", "is_correct": false, "rationale": "Deletion remains unsafe without evaluating representativeness and systematic causes; the source specifically calls for assessing how missing values affect the data set.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "C", "text": "Join timestamps and crew locations to nearby master assets, validate candidate matches with knowledgeable staff and samples, and retain match confidence and provenance.", "is_correct": true, "rationale": "The corpus describes this forensic linkage as a practical way to recover missing asset identifiers, while emphasizing the need for deep data knowledge.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "D", "text": "Assign each inspection to the nearest asset using crew location alone and treat every candidate match as certain.", "is_correct": false, "rationale": "Location alone does not establish identity; the described recovery method also uses timestamps and requires substantial knowledge of the data.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}]}, {"question_id": "CAPX-D3-Q006", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.2.4", "CAP-X 3.2.5"], "topic": "Architecture implications for a recurring analytics application", "section": "", "difficulty": "advanced", "stem": "A forecasting analysis that once ran monthly from spreadsheets must now refresh hourly inside an operational application using four source systems. Which architecture implication is most important?", "correct_key": "A", "options": [{"key": "A", "text": "Create monitored, repeatable ingestion and transformation pipelines into an operational store or warehouse that supplies current, complete, analysis-ready data to the application.", "is_correct": true, "rationale": "Recurring applications require current and complete data, an ETL-style integration environment, and supporting data infrastructure rather than one-time manual preparation.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}, {"key": "B", "text": "Keep the monthly spreadsheet process and run it hourly, since unchanged model logic means the integration architecture need not change.", "is_correct": false, "rationale": "The refresh rate and operational use change the data architecture requirements even if model logic is stable.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}, {"key": "C", "text": "Connect the model directly to source systems with embedded credentials and query them at scoring time to reduce data latency.", "is_correct": false, "rationale": "This ignores security and governance responsibilities and is not a sound connection strategy.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "D", "text": "Have analysts copy data from four systems into temporary files each hour and remove those files after every application run.", "is_correct": false, "rationale": "Manual repeated integration is brittle and fails to establish the sustainable infrastructure an application needs.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}]}, {"question_id": "CAPX-D3-Q007", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.2.6"], "topic": "Relational database relationships", "section": "", "difficulty": "moderate", "stem": "An asset table contains one row per asset keyed by Asset_ID. A work-order table contains many service records for the same asset and also includes Asset_ID. Which statement is correct?", "correct_key": "D", "options": [{"key": "A", "text": "Require Asset_ID to be unique in both tables so every asset and work order has exactly one matching row.", "is_correct": false, "rationale": "An asset can legitimately have many work orders, so the foreign key repeats in the transaction table.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.4.1 Relational Databases"}]}, {"key": "B", "text": "Define Asset_ID as a foreign key in the asset table and a primary key in work orders, then join on it.", "is_correct": false, "rationale": "The roles are reversed: it uniquely identifies the asset master record and relates repeated work orders back to it.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.4.1 Relational Databases"}]}, {"key": "C", "text": "Keep the tables separate because their row counts differ, summarizing each independently before comparing aggregate results.", "is_correct": false, "rationale": "One-to-many relationships are a core relational pattern and are joined using primary and foreign keys.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.4.1 Relational Databases"}]}, {"key": "D", "text": "Asset_ID is the asset table's primary key and a work-order foreign key, forming a one-to-many relationship that avoids repeating asset attributes in every service record.", "is_correct": true, "rationale": "This is the relational design described for assets and work orders.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.4.1 Relational Databases"}]}]}, {"question_id": "CAPX-D3-Q008", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.2.7"], "topic": "The four Vs and architecture", "section": "", "difficulty": "advanced", "stem": "A monitoring program receives thousands of sensor events per second, retains petabytes, combines numeric streams with images and notes, and knows that some sensors drift. Which interpretation of the four Vs is best?", "correct_key": "B", "options": [{"key": "A", "text": "Treat volume as the dominant concern because petabyte storage determines the main architecture, while the other Vs can be handled downstream.", "is_correct": false, "rationale": "Velocity and variety also shape data management, while veracity determines whether the solution can be trusted.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "B", "text": "Volume affects storage and computation; velocity affects ingestion-to-action latency; variety affects representation and integration; veracity requires quality controls for drift and error.", "is_correct": true, "rationale": "The mapping correctly connects each V to the project's architecture or evidentiary quality needs.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "Veracity means the data arrive quickly, while velocity means the data are accurate.", "is_correct": false, "rationale": "The definitions are reversed: veracity concerns quality and velocity concerns generation and action speed.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "D", "text": "Resolve variety by converting every source to plain text before analysis and using one parser for all incoming events.", "is_correct": false, "rationale": "A single superficial format does not preserve the structures and meanings of heterogeneous sources.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}]}, {"question_id": "CAPX-D3-Q009", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.3.1"], "topic": "Data management plan and governance culture", "section": "", "difficulty": "advanced", "stem": "A company has repeated analytics failures because teams cannot agree who owns source definitions or approves access and quality fixes. Which data-management plan is strongest?", "correct_key": "C", "options": [{"key": "A", "text": "Let each project define ownership, access, and quality rules independently, reconciling differences only when data are shared.", "is_correct": false, "rationale": "Project-specific improvisation perpetuates inconsistency and leaves shared data unmanaged.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}, {"key": "B", "text": "Assign governance decisions to the modeling team because it understands downstream use, consulting owners only for access exceptions.", "is_correct": false, "rationale": "Modelers are important consumers, but stewardship, ownership, security, and approval roles extend beyond one project.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "Co-design ownership, stewardship, access and approval rules; maintain metadata and source inventories; monitor quality; preserve raw data and change history; and establish escalation and review routines.", "is_correct": true, "rationale": "This combines explicit governance responsibilities with systematic documentation, stewardship, quality monitoring, and traceable changes.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}, {"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}, {"key": "D", "text": "Centralize source copies and standardize formats while allowing each team to keep separate definitions and quality thresholds.", "is_correct": false, "rationale": "Physical consolidation alone does not create governance, shared meaning, or accountable quality management.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}]}, {"question_id": "CAPX-D3-Q010", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.4.1"], "topic": "Data-source tradeoffs", "section": "", "difficulty": "advanced", "stem": "A quality team can choose among a new manual inspection, existing automated production logs, and a cleansed third-party benchmark. Which assessment is most defensible?", "correct_key": "A", "options": [{"key": "A", "text": "Manual inspection can target the question but introduces recording and judgment error; automated logs reduce manual entry but may reflect another purpose; third-party data arrive cleansed but still require project-fit assessment.", "is_correct": true, "rationale": "The comparison matches the documented distinctions: purpose-built manual collection can contain human error, automated operational data may serve another objective, and third-party providers deliver cleansed usable data whose suitability still must be assessed.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}, {"key": "B", "text": "Prioritize the purpose-built inspection because trained experts can target the question, treating calibration and repeated sampling as sufficient quality controls.", "is_correct": false, "rationale": "Manual collection creates opportunities for keystroke, omission, threshold, and judgment errors.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}, {"key": "C", "text": "Prioritize automated logs because scale and reduced entry error make them suitable once formats and missing values are checked.", "is_correct": false, "rationale": "Operational data may have been specified for another objective and can require augmentation and transformation.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}, {"key": "D", "text": "Prefer the benchmark because external cleansing makes it usable, and assume its industry definitions transfer after confirming subscription access.", "is_correct": false, "rationale": "External cleansing can make data usable, but it does not establish an exact fit with the project's objective or local definitions.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}, {"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}]}]}, {"question_id": "CAPX-D3-Q011", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.4.2"], "topic": "Ethical and privacy-aware data acquisition", "section": "", "difficulty": "advanced", "stem": "A wellness project requests detailed employee location histories even though aggregate shift patterns may be sufficient. What is the best acquisition approach?", "correct_key": "D", "options": [{"key": "A", "text": "Collect precise histories for all employees under restricted access, anticipating future questions even though aggregate patterns may answer the current one.", "is_correct": false, "rationale": "Collecting personal data beyond the granularity needed for the target question expands privacy and security exposure without established current value.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "B", "text": "Proceed after verbal project-manager approval, documenting the conversation as sufficient authorization for purpose, access, and retention.", "is_correct": false, "rationale": "Permission and conditions of use require accountable governance, not an informal single-person exception.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "Remove names and employee IDs, retain exact location sequences indefinitely, and allow broad analytic access because direct identifiers are absent.", "is_correct": false, "rationale": "Removing direct identifiers does not establish permission for unrestricted access or retention; personal location histories still raise privacy and security concerns.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "D", "text": "First determine whether aggregate patterns answer the question; if detailed personal data remain necessary, negotiate approved access and conditions of use, document source and origin, and apply appropriate privacy and security controls.", "is_correct": true, "rationale": "The approach avoids unnecessary granularity and, if detailed records are justified, follows the documented requirements for source records, confidentiality, access conditions, privacy, and security.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}]}, {"question_id": "CAPX-D3-Q012", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.4.3"], "topic": "Lineage, traceability, and version control", "section": "", "difficulty": "moderate", "stem": "A regulator asks the team to reproduce the exact training data used six months ago and explain every transformation. Which practice best satisfies the request?", "correct_key": "B", "options": [{"key": "A", "text": "Retain only the latest cleaned table and a high-level summary, assuming unversioned backups can reconstruct every original source later.", "is_correct": false, "rationale": "Overwriting prior states destroys reproducibility and the ability to inspect original evidence.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "B", "text": "Catalog every source's owner, origin, format, and access conditions; archive captured data in original form with what, when, and from whom; and document every transformation and format change.", "is_correct": true, "rationale": "Those practices directly preserve source identity, capture history, original evidence, and documented changes needed to reproduce the analytic data.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "Save the final analytic table, model outputs, and screenshots, but omit the original source records and intermediate changes.", "is_correct": false, "rationale": "A final table and output images cannot recreate the original input records or undocumented intermediate transformations.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "D", "text": "Record source filenames in analyst notes and ask the original analyst to explain undocumented transformations during any later review.", "is_correct": false, "rationale": "Personal memory is not a durable, auditable traceability mechanism.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}]}, {"question_id": "CAPX-D3-Q013", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.5.1"], "topic": "Harmonizing conflicting sources", "section": "", "difficulty": "advanced", "stem": "Two plants report energy use under the same field name, but one records kilowatt-hours at local midnight and the other records megajoules at UTC midnight. How should the team merge the data?", "correct_key": "C", "options": [{"key": "A", "text": "Append both plants after matching date labels, then average overlaps so unit and boundary differences cancel in aggregate.", "is_correct": false, "rationale": "The units and time boundaries are not comparable, so blind averaging creates meaningless results.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.16 JTA Domain III, Task 3: Harmonize, Rescale, Clean, and Share Data"}]}, {"key": "B", "text": "Keep the larger plant values because their magnitude supplies more signal, standardizing only field names and formats.", "is_correct": false, "rationale": "Magnitude here reflects units, not evidentiary quality or business relevance.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "Confirm definitions with source owners, convert to a canonical unit and time boundary, use stable keys, preserve original fields and provenance, and validate reconciled totals before modeling.", "is_correct": true, "rationale": "Multi-source conflicts can arise from units, staleness, and errors and should be explicitly resolved with business knowledge and stakeholder collaboration.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.16 JTA Domain III, Task 3: Harmonize, Rescale, Clean, and Share Data"}]}, {"key": "D", "text": "Exclude the plant with fewer records and model the other source first, treating harmonization as unnecessary for the pilot.", "is_correct": false, "rationale": "Excluding an entire source without assessing impact sacrifices coverage rather than solving the conflicting-needs problem.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.16 JTA Domain III, Task 3: Harmonize, Rescale, Clean, and Share Data"}]}]}, {"question_id": "CAPX-D3-Q014", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.5.2"], "topic": "Transformation choices for future modeling", "section": "", "difficulty": "advanced", "stem": "A customer table contains an email-address field with nearly one unique value per row. The team proposes one indicator variable for every address in a linear model. What is the best response?", "correct_key": "A", "options": [{"key": "A", "text": "Treat the field as high-cardinality; determine whether it is useful, then discard it or derive a defensible lower-cardinality feature such as domain or region.", "is_correct": true, "rationale": "High-cardinality identifiers provide too few observations per level and are typically removed or transformed through meaningful binning.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "B", "text": "Create an indicator for every address and select them by in-sample fit, without checking observations per level or out-of-sample behavior.", "is_correct": false, "rationale": "Near-unique levels have too few observations per level for the proposed linear model; in-sample selection does not supply the missing replication.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "C", "text": "Replace each email address with a stable numeric code so the linear model can use identity without a full indicator matrix.", "is_correct": false, "rationale": "Stable numeric identity codes fabricate order and distance for a nominal field and do not solve the high-cardinality problem.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.1 Data Types"}]}, {"key": "D", "text": "Sort addresses by domain and name, assign consecutive ranks, and treat those ranks as continuous after normalization.", "is_correct": false, "rationale": "Alphabetical order has no defensible quantitative meaning and would fabricate distances between identities.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.1 Data Types"}]}]}, {"question_id": "CAPX-D3-Q015", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.6.1"], "topic": "Diagnosing systematic missingness", "section": "", "difficulty": "advanced", "stem": "In an employee survey, income is missing much more often for senior roles. The team plans to replace every missing income with the overall mean and proceed. What should happen first?", "correct_key": "D", "options": [{"key": "A", "text": "Use mean imputation within each role without first investigating why senior employees omit income, because role-specific averages preserve local levels.", "is_correct": false, "rationale": "Mean imputation can dilute relationships and does not resolve systematic nonresponse bias.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "B", "text": "Delete all records with missing responses after confirming the remaining sample is large enough for model training.", "is_correct": false, "rationale": "The impact should be assessed before rejecting all otherwise usable data.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "C", "text": "Treat blanks as missing completely at random because no value was recorded, then apply standard multiple imputation.", "is_correct": false, "rationale": "Missingness mechanisms depend on patterns and causes; role-related nonresponse is evidence against complete randomness.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "D", "text": "Create a response indicator, compare observed characteristics of response and nonresponse groups, treat the role pattern as possible nonrandom missingness, and assess bias before choosing a documented remedy.", "is_correct": true, "rationale": "Comparing response groups helps detect nonresponse bias, which changes whether deletion or imputation is defensible.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}]}, {"question_id": "CAPX-D3-Q016", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.6.1"], "topic": "Outlier and noise treatment", "section": "", "difficulty": "advanced", "stem": "A predictive-maintenance feed contains extreme temperature spikes. Some are known sensor malfunctions; others coincide with real overheating events. What is the best treatment?", "correct_key": "B", "options": [{"key": "A", "text": "Remove every reading more than three standard deviations from the mean, then refit thresholds on the trimmed series.", "is_correct": false, "rationale": "A fixed rule can remove genuine, predictive rare events and introduce bias.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "B", "text": "Investigate causes with equipment experts, flag or remove verified errors, retain genuine events with robust transformations or methods as needed, and document rules and sensitivity.", "is_correct": true, "rationale": "Outlier remedies depend on cause: erroneous extremes may be discarded, while recurring real extremes can carry valuable information and may need transformation.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "C", "text": "Cap all spikes at the same percentile and retain the modified data, documenting only the final transformation rule.", "is_correct": false, "rationale": "A documented uniform cap still ignores the known difference in cause and may merge sensor malfunctions with genuine overheating events.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "D", "text": "Smooth the series until extremes no longer dominate, then train the failure model on the filtered trend.", "is_correct": false, "rationale": "Smoothing can reduce noise but may also erase the event the model is intended to detect.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}]}, {"question_id": "CAPX-D3-Q017", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.6.2"], "topic": "Multivariate profiling and collinearity", "section": "", "difficulty": "advanced", "stem": "Data profiling shows that supplier name and source country are almost perfectly correlated because each supplier operates in one country. Both are proposed as predictors in an interpretable linear model. What is the best next step?", "correct_key": "C", "options": [{"key": "A", "text": "Keep both variables because their distinct labels may capture separate effects, without checking coefficient stability or redundancy.", "is_correct": false, "rationale": "They contain redundant information and can destabilize parameter estimation rather than add independent evidence.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "B", "text": "Remove source country because it has fewer categories, without examining which variable better represents the business hierarchy.", "is_correct": false, "rationale": "Category count alone does not identify the more descriptive representation; the documented concern is redundant information and model-parameter estimation.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "C", "text": "Examine the business hierarchy and retain the more descriptive of the two redundant variables, documenting the choice and its interpretability implications.", "is_correct": true, "rationale": "The cited passage uses this supplier-country hierarchy as its example and recommends limiting inclusion to the most descriptive variable because collinearity creates redundant information and estimation difficulty.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "D", "text": "Encode both categories as ordered integers and retain them together so the model can distinguish their supposed hierarchical levels.", "is_correct": false, "rationale": "Arbitrary numeric codes fabricate order and distance for nominal data.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.1 Data Types"}]}]}, {"question_id": "CAPX-D3-Q018", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.6.3"], "topic": "Interpreting a visual relationship", "section": "", "difficulty": "advanced", "stem": "A scatterplot of advertising spend versus weekly sales shows a generally upward pattern, but three high-spend weeks are far from the rest and coincide with a holiday campaign. Which conclusion is clearest and most defensible?", "correct_key": "A", "options": [{"key": "A", "text": "Spend and sales show a positive observed relationship, while the holiday weeks may be influential; compare analyses with and without them, and do not infer causation from the plot alone.", "is_correct": true, "rationale": "Scatter plots support exploration of relationships, unusual points require cause-sensitive treatment, and an observed correlation does not by itself imply causation.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group I: Solution Techniques"}, {"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}, {"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.3.2 Predictive Analytics"}]}, {"key": "B", "text": "Attribute the sales increase to advertising because the fitted slope is positive and the holiday points follow the same direction.", "is_correct": false, "rationale": "The observed relationship does not establish causation; the holiday campaign is an explicit reason to investigate other structure before making that claim.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.3.2 Predictive Analytics"}]}, {"key": "C", "text": "Remove the three holiday weeks before fitting the relationship because visually distant observations would otherwise dominate the slope.", "is_correct": false, "rationale": "Outliers require investigation; recurring or explainable extremes can contain valuable information.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}, {"key": "D", "text": "Conclude there is no usable association because ordinary and holiday points do not form a near-perfect line across the spend range.", "is_correct": false, "rationale": "Scatter plots are used to explore relationships and correlation; visible variation does not by itself erase the generally upward relationship stated in the scenario.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group I: Solution Techniques"}]}]}, {"question_id": "CAPX-D3-Q019", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.6.4"], "topic": "Evaluating and mitigating data-quality issues", "section": "", "difficulty": "advanced", "stem": "A customer data set contains duplicate IDs, invalid status codes, stale contact dates, and missing region values. What is the strongest quality assessment?", "correct_key": "D", "options": [{"key": "A", "text": "Compute completeness and duplicate rates for each field, then treat those two measures as the overall quality assessment.", "is_correct": false, "rationale": "Completeness alone does not assess uniqueness, validity, timeliness, or cross-field consistency.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "B", "text": "Correct invalid and missing values only when they prevent model execution, leaving stale or inconsistent records unchanged.", "is_correct": false, "rationale": "Executable data can still be inaccurate, stale, inconsistent, or misleading for the business purpose.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "Repair the current file and record final changes, but postpone capture-control improvements and recurring steward review to a later project.", "is_correct": false, "rationale": "One-time repair leaves the root causes and future reproducibility unresolved.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}, {"key": "D", "text": "Profile and quantify duplicates, invalid values, staleness, missingness, and consistency; assess analytic impact, assign remediation to data owners or stewards, improve capture controls, and document remedies.", "is_correct": true, "rationale": "Profiling identifies missing, inconsistent, and invalid data, while documented remedies, source responsibility, stewardship, and improved capture controls help keep the data reliable and usable.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}, {"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.5 Data Management"}]}]}, {"question_id": "CAPX-D3-Q020", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.7.1"], "topic": "Reporting data applicability", "section": "", "difficulty": "advanced", "stem": "A retailer's training data cover only app users, who are younger and more urban than store-only customers. The sponsor asks whether the model can be applied to all customers. What is the most valid conclusion?", "correct_key": "B", "options": [{"key": "A", "text": "Generalize to store-only customers because millions of app records provide stable estimates even if channel participation differs.", "is_correct": false, "rationale": "Large volume does not correct systematic undercoverage of different customer groups.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "B", "text": "Applicability to store-only customers is unproven and may be biased; report the coverage gap and subgroup implications, restrict use or collect representative data, and define validation before expansion.", "is_correct": true, "rationale": "Digital-source samples can be unrepresentative, and data findings and limitations should be communicated to stakeholders.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.18 JTA Domain III, Task 5: Document and Report Finding"}]}, {"key": "C", "text": "Remove protected attributes before scoring and assume the remaining app sample is representative enough for cross-channel use.", "is_correct": false, "rationale": "Removing fields does not make the sampled population representative or eliminate proxy effects.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "D", "text": "Restrict the model permanently to app users and reject any expansion study because the current sample lacks store-only observations.", "is_correct": false, "rationale": "Generalization can be evaluated with representative evidence; the current gap calls for validation or scope limits, not automatic abandonment.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.3 Data Preparation"}]}]}, {"question_id": "CAPX-D3-Q021", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X 3.8.1"], "topic": "Updating problem statements after data findings", "section": "", "difficulty": "advanced", "stem": "A project was framed to predict individual daily demand, but discovery shows that historical demand exists only as monthly region totals and cannot be disaggregated. What should the analytics professional do?", "correct_key": "C", "options": [{"key": "A", "text": "Allocate regional totals to synthetic individuals using population weights and retain the individual-daily claim, labeling outputs as modeled estimates.", "is_correct": false, "rationale": "Synthetic allocation does not supply observed individual outcomes or make aggregate data disaggregatable, so it cannot support the original granularity.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "B", "text": "Deliver monthly regional forecasts as an interim output while retaining the individual-daily success criteria and original approval unchanged.", "is_correct": false, "rationale": "A material change in unit and horizon requires revised problem statements and updated stakeholder agreement rather than leaving the original criteria and approval unchanged.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.18 JTA Domain III, Task 6: Refine the Business and Analytics Problem Statements"}]}, {"key": "C", "text": "Document the granularity finding and business impact, revise the analytic statement to a supportable monthly regional forecast or propose new collection for the original objective, then seek updated stakeholder approval.", "is_correct": true, "rationale": "Data understanding is expected to change project plans; both problem statements should be updated and presented for renewed agreement.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.18 JTA Domain III, Task 6: Refine the Business and Analytics Problem Statements"}]}, {"key": "D", "text": "Fit a hierarchical model to infer individual daily demand from aggregates without new data or explicit identifying assumptions.", "is_correct": false, "rationale": "Greater model complexity cannot make aggregated data disaggregatable; individual daily detail requires additional assumptions or evidence not present in the source.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}]}, {"question_id": "CAPX-D4-Q001", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.1.1"], "topic": "Method selection from the business problem", "section": "", "difficulty": "advanced", "stem": "A city asks an analytics team to 'use AI to improve emergency response.' The sponsor has not specified which operational decision will change, the acceptable response-time target, the budget, or when a recommendation is needed. What should the lead analytics professional do first when selecting a methodology?", "correct_key": "A", "options": [{"key": "A", "text": "Clarify the decision, desired outcome, success measure, constraints, and decision deadline before comparing candidate methods.", "is_correct": true, "rationale": "Correct. Method selection must start from the actual problem and level of solution sought; timing and constraints can rule methods in or out.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.5.3 \u201cThere Is Only One Way to Solve This\u201d"}]}, {"key": "B", "text": "Choose the most accurate deep-learning method available and then define a use case around its output.", "is_correct": false, "rationale": "This is technology-first. A familiar or fashionable method is not a substitute for understanding the problem and comparing alternatives.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.5.3 \u201cThere Is Only One Way to Solve This\u201d"}]}, {"key": "C", "text": "Begin collecting every available public-safety data set because more data will identify the method automatically.", "is_correct": false, "rationale": "Data matter, but the modeling approach and domain problem frame should precede decisions about how data will be leveraged.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.3.1 Micro-Solution Methodology Preliminaries"}]}, {"key": "D", "text": "Select the cheapest software package and use whichever method it supports most easily.", "is_correct": false, "rationale": "Software cost is one selection factor, but tools must fit the target problem, data, infrastructure, and communication requirements.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.4 Task 4: Selecting Analytics Tools (see also Chapters 5 and 6 )"}]}]}, {"question_id": "CAPX-D4-Q002", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.1.2"], "topic": "Diagnostic method selection", "section": "", "difficulty": "moderate", "stem": "A plant's first-pass yield fell last month. Leaders want to know which process factors are associated with the decline before they consider an intervention. Which initial approach best fits the analytics problem?", "correct_key": "B", "options": [{"key": "A", "text": "Optimize the production schedule immediately to maximize total output.", "is_correct": false, "rationale": "Optimization prescribes actions; it does not first diagnose which observed factors explain the yield decline.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}, {"key": "B", "text": "Profile the data, visualize factor-yield relationships, and use regression or ANOVA to test plausible contributors.", "is_correct": true, "rationale": "Correct. Descriptive statistics, plots, regression, and ANOVA support exploration and diagnosis of relationships and sources of variation.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group I: Solution Techniques"}]}, {"key": "C", "text": "Fit a forecasting model for next quarter's yield without examining current factor relationships.", "is_correct": false, "rationale": "Forecasting addresses future values, while the stated need is to explain a recent decline and its associated factors.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.3.2 Predictive Models"}]}, {"key": "D", "text": "Simulate a new plant layout before verifying whether layout is related to the decline.", "is_correct": false, "rationale": "Simulation is useful for what-if experimentation, but this option prematurely assumes the causal mechanism that must first be investigated.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Problems of Interest"}]}]}, {"question_id": "CAPX-D4-Q003", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.1.2"], "topic": "Unsupervised descriptive segmentation", "section": "", "difficulty": "moderate", "stem": "A nonprofit has donor attributes and giving histories but no predefined donor segments or segment labels. It wants to discover naturally occurring groups for exploratory planning. Which method is most appropriate?", "correct_key": "C", "options": [{"key": "A", "text": "Time-series forecasting of total monthly donations.", "is_correct": false, "rationale": "Time-series models describe or forecast change over time; they do not directly discover unlabeled groups of donors.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.4 Time Series Forecasting"}]}, {"key": "B", "text": "Supervised classification using a segment label as the response.", "is_correct": false, "rationale": "Supervised classification requires a labeled categorical response, which the scenario explicitly lacks.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.2 Supervised, Unsupervised, and Reinforcement Learning"}]}, {"key": "C", "text": "Clustering based on a defined similarity measure, followed by interpretation of the resulting groups.", "is_correct": true, "rationale": "Correct. Clustering is an unsupervised approach for revealing hidden groups of observations that are more similar within group than across groups.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.7.3 Clustering Methods"}]}, {"key": "D", "text": "Integer programming to assign every donor to the segment that maximizes donations.", "is_correct": false, "rationale": "Integer programming requires a defined objective, decisions, and constraints; it is not the initial method for discovering latent structure without labels.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}]}, {"question_id": "CAPX-D4-Q004", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.1.3"], "topic": "Predictive time-series methodology", "section": "", "difficulty": "advanced", "stem": "A contact center must forecast next week's call volume. Volume has a weekly seasonal pattern, and recent observations are more relevant than older ones. Which methodology and evaluation design best match the problem?", "correct_key": "D", "options": [{"key": "A", "text": "Cluster weeks by call-volume features, use random train-test splits, and treat cluster stability as next-week forecast accuracy.", "is_correct": false, "rationale": "Clustering discovers groups and does not forecast a numeric time-indexed response; random splits also ignore temporal order.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.7.3 Clustering Methods"}]}, {"key": "B", "text": "A cross-sectional logistic classifier evaluated only on training accuracy.", "is_correct": false, "rationale": "The response is numeric call volume, not a category, and training accuracy is not a valid estimate of future performance.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}, {"key": "C", "text": "A static descriptive mean, with no treatment of seasonality or time order.", "is_correct": false, "rationale": "A descriptive mean may summarize history but omits the temporal dependence and seasonal structure needed for the forecast.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.4 Time Series Forecasting"}]}, {"key": "D", "text": "A seasonal time-series model, evaluated with rolling-origin forecasts that always train on earlier periods and test on later periods.", "is_correct": true, "rationale": "Correct. Time-series models represent trend and seasonality, and rolling-horizon evaluation respects time dependency.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.3 Performance Evaluation for Time-Dependent Data"}]}]}, {"question_id": "CAPX-D4-Q005", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.1.3"], "topic": "Interpretable predictive method selection", "section": "", "difficulty": "advanced", "stem": "A public benefits agency needs a predictive classifier for case review. Policy requires staff to explain the principal decision path to an applicant. Several methods have similar out-of-sample performance. Which method is the strongest initial candidate?", "correct_key": "A", "options": [{"key": "A", "text": "A pruned classification tree, with performance and subgroup behavior validated on representative holdout data.", "is_correct": true, "rationale": "Correct. A pruned tree is visually interpretable and can satisfy an explanation requirement while still being evaluated for generalization.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.3 Classification and Regression Trees"}]}, {"key": "B", "text": "The deepest neural network available because complexity guarantees fairness.", "is_correct": false, "rationale": "Neural networks can require more data and computation and may be nearly uninterpretable; complexity does not guarantee fairness.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.6 Artificial Neural Networks"}]}, {"key": "C", "text": "An unpruned tree grown until every training leaf is pure.", "is_correct": false, "rationale": "A fully pure training tree is usually overfit and is less likely to generalize to new applicants.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.3 Classification and Regression Trees"}]}, {"key": "D", "text": "Whichever model has the best training-set fit, regardless of interpretability.", "is_correct": false, "rationale": "Training fit overstates predictive performance, and interpretability is a legitimate selection criterion in public-policy applications.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.3.7 Model (Algorithm) Selection"}]}]}, {"question_id": "CAPX-D4-Q006", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.1.4"], "topic": "Prescriptive scheduling methodology", "section": "", "difficulty": "moderate", "stem": "A hospital must assign nurses to shifts while meeting coverage, credential, rest-period, and budget rules, and it wants to minimize total overtime. Which method best fits this analytics problem?", "correct_key": "B", "options": [{"key": "A", "text": "Unsupervised clustering of nurses by historical shift preference.", "is_correct": false, "rationale": "Clustering may reveal groups but does not directly choose a feasible schedule that minimizes overtime under constraints.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.7.3 Clustering Methods"}]}, {"key": "B", "text": "Mixed-integer optimization with binary assignment decisions, a total-overtime objective, and the operational rules as constraints.", "is_correct": true, "rationale": "Correct. Discrete assignment decisions plus an objective and feasibility constraints are a prescriptive mixed-integer optimization structure.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}, {"key": "C", "text": "A descriptive dashboard of last month's overtime by unit.", "is_correct": false, "rationale": "The dashboard describes prior outcomes but does not prescribe future assignments under the required rules.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.3.1 Descriptive Models"}]}, {"key": "D", "text": "Linear regression predicting each nurse's overtime hours, used directly as the assignment plan.", "is_correct": false, "rationale": "Regression predicts a response from explanatory variables; without decisions, constraints, and an objective it does not produce a feasible assignment plan.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.9.4 Regression 9 , 10"}]}]}, {"question_id": "CAPX-D4-Q007", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.1.4"], "topic": "Prescriptive what-if simulation", "section": "", "difficulty": "advanced", "stem": "An emergency department wants to compare alternative triage and staffing policies before changing live operations. Arrivals and service times are random, queues interact, and the team needs wait-time and utilization distributions. Which approach is most appropriate?", "correct_key": "C", "options": [{"key": "A", "text": "A confidence interval for the historical mean wait time only.", "is_correct": false, "rationale": "A confidence interval summarizes current performance but does not represent interacting queues or compare candidate operating policies.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group I: Solution Techniques"}]}, {"key": "B", "text": "A clustering model of patient records.", "is_correct": false, "rationale": "Clustering can segment observations but does not emulate the dynamic sequence of arrivals, service events, and queue-state changes.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.7.3 Clustering Methods"}]}, {"key": "C", "text": "A stochastic discrete-event simulation of arrivals, services, resources, and policy rules, with replicated output analysis.", "is_correct": true, "rationale": "Correct. Discrete-event simulation represents time, events, states, queues, and random inputs, enabling safe what-if experiments; its outputs must be analyzed statistically.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}, {"key": "D", "text": "A deterministic spreadsheet that replaces each random input with its average and reports one run.", "is_correct": false, "rationale": "Replacing all uncertainty with averages and using one run loses the distributional behavior requested and cannot support statistical output analysis.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Data Considerations"}]}]}, {"question_id": "CAPX-D4-Q008", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.1.5"], "topic": "Appropriate use of Generative AI", "section": "", "difficulty": "advanced", "stem": "A consumer-protection team has 80,000 free-text complaint narratives. Analysts must quickly draft candidate themes and concise summaries, but every conclusion must remain traceable to source text. Which use of Generative AI best addresses the problem?", "correct_key": "D", "options": [{"key": "A", "text": "Let a language model issue final enforcement decisions directly from the narratives, with no human review.", "is_correct": false, "rationale": "This turns a summarization aid into an unreviewed consequential decision-maker and omits controls for error, explainability, and accountability.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "B", "text": "Use generated themes as ground-truth labels for a downstream classifier and report only its training-set accuracy.", "is_correct": false, "rationale": "Generated labels are not automatically ground truth, and training-set performance is not a valid estimate of predictive performance.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}, {"key": "C", "text": "Upload all narratives, including personal identifiers, to any public model because text analytics requires broad access.", "is_correct": false, "rationale": "Text analytics may require specialized tools, but PII still requires explicit permission and controlled handling.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.28.3 Personally Identifiable Information"}]}, {"key": "D", "text": "Use a controlled language-model workflow to draft themes and summaries linked to retrieved source passages; require analysts to verify cited evidence and review the generated content before use.", "is_correct": true, "rationale": "Correct. Text analytics calls for task-appropriate tooling, while retrieval grounding, source verification, and human review directly address traceability and confabulation risk.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Analytical Specificity or Breadth"}, {"source": "NIST AI 600-1, Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile", "url": "https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf", "locator": "MEASURE 2.5, actions MS-2.5-002, MS-2.5-003, and MS-2.5-005 (PDF p. 34); MANAGE 3.2, action MG-3.2-008 (PDF p. 47)"}]}]}, {"question_id": "CAPX-D4-Q009", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.2.1"], "topic": "Method trade-offs under constraints", "section": "", "difficulty": "advanced", "stem": "A regulator needs a model that can be explained case by case. The team has 4,000 labeled observations, limited compute, and a two-month deadline. A neural network improves validation AUC from 0.79 to 0.80 over a regularized logistic model. What is the best selection decision?", "correct_key": "A", "options": [{"key": "A", "text": "Prefer the simpler interpretable model unless the small predictive gain has demonstrated business value that outweighs explanation, data, compute, and deployment costs.", "is_correct": true, "rationale": "Correct. Predictive performance is not the only criterion; interpretability, speed, deployability, resource cost, and business impact all matter.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.3.7 Model (Algorithm) Selection"}]}, {"key": "B", "text": "Always select the neural network because any increase in AUC dominates all other criteria.", "is_correct": false, "rationale": "A small gain does not automatically dominate interpretability, computational cost, and deployability, especially in a regulated use.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.6 Artificial Neural Networks"}]}, {"key": "C", "text": "Select by training AUC because the data set is too small to reserve holdout data.", "is_correct": false, "rationale": "Training performance usually overestimates field performance; model selection requires out-of-sample evaluation.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}, {"key": "D", "text": "Choose the method the current analyst already knows, even if it cannot meet the explanation requirement.", "is_correct": false, "rationale": "Team skill is relevant, but the tool and method must meet project needs; training or added expertise may be required.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Data Scientist Skillset"}]}]}, {"question_id": "CAPX-D4-Q010", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.2.1"], "topic": "Rapid method comparison", "section": "", "difficulty": "moderate", "stem": "A sponsor needs a useful prototype in two weeks. Data quality is uncertain, and no method has yet demonstrated acceptable accuracy. What is the most defensible approach to method selection?", "correct_key": "B", "options": [{"key": "A", "text": "Commit now to the team's familiar method, tune it for two weeks, and compare alternatives only if accuracy misses the target.", "is_correct": false, "rationale": "Familiarity can help, but assuming one favorite method is best ignores alternatives and the uncertain data conditions.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.5.3 \u201cThere Is Only One Way to Solve This\u201d"}]}, {"key": "B", "text": "Rapidly prototype a small set of plausible methods on representative data, compare benefits, limitations, risks, and resource needs against agreed success criteria, then select or iterate.", "is_correct": true, "rationale": "Correct. Rapid prototypes make trade-offs visible while preserving a systematic, evidence-based selection process under time constraints.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.5.3 \u201cThere Is Only One Way to Solve This\u201d"}]}, {"key": "C", "text": "Build a rapid prototype, but postpone independent verification until after limited deployment because users will manually review its output.", "is_correct": false, "rationale": "Even packaged methods and prototypes require verification; temporary status does not remove the risk of incorrect results.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.4.2 Software and Tool Selection"}]}, {"key": "D", "text": "Collect all conceivable data before testing any method, even if that makes the deadline impossible.", "is_correct": false, "rationale": "Data acquisition has real cost; the goal is to solve the target problem, not gather everything that might ever be useful.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}]}, {"question_id": "CAPX-D4-Q011", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.3.1"], "topic": "Technical solution architecture", "section": "", "difficulty": "advanced", "stem": "A manufacturer needs to score high-velocity sensor events within five seconds, retain raw events for audit, and retrain models monthly. Which architecture best supports the solution?", "correct_key": "C", "options": [{"key": "A", "text": "Use an automated monthly spreadsheet extract that emails scores within five seconds of each workbook refresh and retains monthly files.", "is_correct": false, "rationale": "Fast scoring after a monthly refresh still cannot score high-velocity events within five seconds of arrival.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "B", "text": "Use a batch warehouse that retains monthly averages for retraining but discards event-level captures and serves scores on the next batch.", "is_correct": false, "rationale": "Discarding raw events conflicts with auditability and retraining, and batch scoring does not satisfy the scoring latency.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "C", "text": "A recurring ingestion and transformation process feeding an operational store or warehouse, with time-stamped raw data retained and an execution path sized for five-second scoring and monthly retraining.", "is_correct": true, "rationale": "Correct. Recurring applications require current, complete data and sustainable ETL-style infrastructure; velocity and available infrastructure determine execution performance, while archived raw captures support later reference.", "citations": [{"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "4.2.2 Data Discovery"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Execution Performance"}]}, {"key": "D", "text": "One monolithic modeling notebook that performs ingestion, scoring, storage, retraining, and user access in a single interactive session.", "is_correct": false, "rationale": "A notebook can prototype logic, but this option omits production separation, reliability, monitoring, and performance provisions implied by the operational requirements.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.4.1 Planning an Analytics Project"}]}]}, {"question_id": "CAPX-D4-Q012", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.4.1"], "topic": "Technology-stack risk evaluation", "section": "", "difficulty": "advanced", "stem": "A health analytics project will use identifiable records. The team is comparing an on-premises platform, a managed cloud service, and open-source components. Which evaluation is most appropriate?", "correct_key": "D", "options": [{"key": "A", "text": "Choose on-premises after confirming capacity and performance, and assume local hosting itself satisfies data-access compatibility and all PII handling requirements.", "is_correct": false, "rationale": "Deployment location alone does not determine security; the choice must be evaluated against specific access, processing, governance, and operational requirements.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Access to Data"}]}, {"key": "B", "text": "Choose open source after confirming data access and team skills, and treat zero license fees as evidence that support and budget risks are minimal.", "is_correct": false, "rationale": "License price is only one factor; support, skills, infrastructure, performance, security, and lifecycle costs also matter.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Vendor Pricing"}]}, {"key": "C", "text": "Choose the managed service for setup speed and adequate performance, then defer PII permissions and storage and use protocols to contract negotiation.", "is_correct": false, "rationale": "Setup time is relevant, but it does not address PII permissions, storage and use protocols, integration, support, or ongoing costs.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.28.3 Personally Identifiable Information"}]}, {"key": "D", "text": "Compare each stack for problem and data fit, access compatibility, required execution and scale, team skills, vendor pricing and budget, support and collaboration, plus the mandated PII storage and use protocols.", "is_correct": true, "rationale": "Correct. ABOK tool selection combines technical requirements, infrastructure and performance, team capability, pricing, budget, and collaboration; identifiable data additionally require explicit permission and special handling protocols.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.4 Task 4: Selecting Analytics Tools (see also Chapters 5 and 6 )"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Access to Data"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Execution Performance"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Data Scientist Skillset"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Vendor Pricing"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Team Budget"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Sharing and Collaboration"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.28.3 Personally Identifiable Information"}]}]}, {"question_id": "CAPX-D4-Q013", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X 4.4.2"], "topic": "Alternatives to spreadsheet models", "section": "", "difficulty": "moderate", "stem": "A successful spreadsheet forecasting prototype is now used by 40 planners. Files are copied by email, formulas are overwritten, data volume is growing, and results must feed an operational system nightly. What is the best next step?", "correct_key": "A", "options": [{"key": "A", "text": "Move the calculation into version-controlled, tested code backed by a governed data store and scheduled service, while preserving a familiar user interface where useful.", "is_correct": true, "rationale": "Correct. Operational scale, collaboration, repeatability, integration, and testing justify moving the model core beyond an emailed spreadsheet without discarding usable interface patterns.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.4.1 Planning an Analytics Project"}]}, {"key": "B", "text": "Continue emailing copies, protect formula cells with passwords, and designate one planner to reconcile the nightly versions.", "is_correct": false, "rationale": "Cell protection and manual reconciliation do not resolve version divergence, lineage, scheduled integration, growing scale, or multi-user collaboration.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Sharing and Collaboration"}]}, {"key": "C", "text": "Replace the spreadsheet with any proprietary package without testing whether it reproduces results.", "is_correct": false, "rationale": "A package change does not remove the obligation to verify that the implementation produces correct results.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.4.2 Software and Tool Selection"}]}, {"key": "D", "text": "Keep the model unchanged because spreadsheets are always sufficient once users understand them.", "is_correct": false, "rationale": "Familiarity is useful, but execution performance, scale, integration, and sharing needs can make a spreadsheet core unsuitable for production.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Execution Performance"}]}]}, {"question_id": "CAPX-D5-Q001", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.1.1"], "topic": "Descriptive and diagnostic model structure", "section": "", "difficulty": "moderate", "stem": "A distribution center wants to understand why orders miss the same-day cutoff. Which model structure is best for an initial descriptive/diagnostic analysis?", "correct_key": "B", "options": [{"key": "A", "text": "Use staffing decision variables and an objective minimizing future labor cost, with the observed delays supplied as parameters.", "is_correct": false, "rationale": "Those elements form a prescriptive optimization model, not an initial descriptive account of observed delays.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}, {"key": "B", "text": "Inputs describing observed order attributes and time stamps at each process stage; outputs showing cycle-time distributions, missed-cutoff rates, and relationships by stage, shift, and order type.", "is_correct": true, "rationale": "Correct. This structure reconciles observed states and actions and supports diagnosis through distributions and relationships.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.3.1 Descriptive Models"}]}, {"key": "C", "text": "Predict a binary next-day cutoff miss for each order, using aggregate order attributes but no process-stage timing.", "is_correct": false, "rationale": "That is a predictive classification output and omits the process-stage relationships needed to diagnose why misses occurred.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.2 Supervised, Unsupervised, and Reinforcement Learning"}]}, {"key": "D", "text": "Analyze employee names and shift assignments without process timing, order attributes, intermediate states, or cutoff outcomes.", "is_correct": false, "rationale": "Names alone do not represent the operational states, intermediate actions, or resulting delay outcomes needed for the analysis.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.3.1 Descriptive Models"}]}]}, {"question_id": "CAPX-D5-Q002", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.1.2"], "topic": "Predictive model inputs and outputs", "section": "", "difficulty": "advanced", "stem": "A subscription company wants to estimate, at each monthly billing date, the probability that an active customer will cancel within 60 days. Which design correctly aligns inputs, response, and output?", "correct_key": "C", "options": [{"key": "A", "text": "Use the cancellation reason recorded after closure as an input and predict current account status.", "is_correct": false, "rationale": "The cancellation reason is unavailable at scoring time and leaks future outcome information into the predictors.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.2 Supervised, Unsupervised, and Reinforcement Learning"}]}, {"key": "B", "text": "Use future 60-day revenue as both an input and the response, then output a customer segment.", "is_correct": false, "rationale": "This mixes future information into the inputs and changes the requested cancellation prediction into an unlabeled segmentation output.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.2 Supervised, Unsupervised, and Reinforcement Learning"}]}, {"key": "C", "text": "Use usage, billing, service, and tenure features available by the billing date; label whether cancellation occurs in the following 60 days; output a calibrated cancellation probability.", "is_correct": true, "rationale": "Correct. Predictors are available at decision time, the categorical future response matches the business event, and the output supports risk-based action.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.2 Supervised, Unsupervised, and Reinforcement Learning"}]}, {"key": "D", "text": "Use only the total number of customers and output the optimal retention budget.", "is_correct": false, "rationale": "An aggregate count lacks customer-level predictive features, and an optimal budget is a prescriptive rather than predictive output.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.3.3 Prescriptive Models"}]}]}, {"question_id": "CAPX-D5-Q003", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.1.3"], "topic": "Prescriptive model structure", "section": "", "difficulty": "moderate", "stem": "A relief organization must plan vehicle routes to deliver all requested supplies while respecting vehicle capacity, driver hours, and road restrictions. It wants to minimize total travel time. Which model structure is appropriate?", "correct_key": "D", "options": [{"key": "A", "text": "Summarize historical routes in a dashboard of average travel time and capacity utilization by region.", "is_correct": false, "rationale": "This structure is descriptive and does not choose routes under operational constraints.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.3.1 Descriptive Models"}]}, {"key": "B", "text": "Predict each delivery's probability of arriving late from road, vehicle, driver, and weather attributes.", "is_correct": false, "rationale": "That is a predictive structure; it estimates an outcome but does not prescribe the route decisions.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.3.2 Predictive Models"}]}, {"key": "C", "text": "Cluster routes from driver comments and historical patterns, then assign each new request to a cluster.", "is_correct": false, "rationale": "Clustering may reveal patterns but omits route choices, feasibility rules, and the travel-time objective.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.7.3 Clustering Methods"}]}, {"key": "D", "text": "Inputs are demand, travel times, capacities, and restrictions; decision variables represent route choices; constraints enforce feasibility; the objective minimizes travel time; output is a feasible route plan.", "is_correct": true, "rationale": "Correct. Prescriptive models require admissible actions, constraints, and an objective that selects the best anticipated outcome.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}]}, {"question_id": "CAPX-D5-Q004", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.2.1"], "topic": "Predictive-model leakage", "section": "", "difficulty": "advanced", "stem": "A hospital model predicts 30-day readmission at discharge. One predictor is a billing code created only after a patient is readmitted. The model performs extremely well in random validation. What is the most important correction?", "correct_key": "A", "options": [{"key": "A", "text": "Remove all fields unavailable at discharge, rebuild features using the scoring-time cutoff, and reevaluate on out-of-sample data that mimics deployment.", "is_correct": true, "rationale": "Correct. Predictors must be available when a prediction is made; otherwise future outcome information contaminates the model and its apparent performance.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.3.1 Goals and Guiding Principles in Machine Learning"}]}, {"key": "B", "text": "Keep the field because its strong association proves it is a valuable causal predictor.", "is_correct": false, "rationale": "Association does not make a post-outcome field available at prediction time; the field makes the evaluation unlike real use.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}, {"key": "C", "text": "Add additional billing fields created after readmission to stabilize the apparent prediction.", "is_correct": false, "rationale": "Adding more unavailable future fields compounds the same leakage and cannot produce a deployable discharge-time predictor.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.2 Supervised, Unsupervised, and Reinforcement Learning"}]}, {"key": "D", "text": "Report training-set performance and subgroup summaries instead of the random-validation result.", "is_correct": false, "rationale": "Training performance is even more optimistic and is not a valid estimate of predictive performance on new cases.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}]}, {"question_id": "CAPX-D5-Q005", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.2.2"], "topic": "Missing prescriptive-model constraints", "section": "", "difficulty": "moderate", "stem": "A production optimization model maximizes contribution margin and selects quantities for each product. Its recommendation exceeds available machine hours and warehouse space. What is missing?", "correct_key": "B", "options": [{"key": "A", "text": "Collect a larger labeled training set for a classifier that predicts which products will exceed capacity.", "is_correct": false, "rationale": "The problem is optimization feasibility, not supervised classification; a training set does not enforce resource limits.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.2 Supervised, Unsupervised, and Reinforcement Learning"}]}, {"key": "B", "text": "Capacity constraints linking product decisions to available machine hours and storage, with consistent units and parameters.", "is_correct": true, "rationale": "Correct. Feasibility in a prescriptive model is defined by equations or inequalities that constrain the decision variables.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}, {"key": "C", "text": "Use a heatmap of correlations among product quantities, machine hours, storage, and margin.", "is_correct": false, "rationale": "A heatmap can aid data exploration but does not impose machine-hour or storage feasibility.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group I: Solution Techniques"}]}, {"key": "D", "text": "Lower a classification threshold so more high-margin products are included in the recommended plan.", "is_correct": false, "rationale": "Classification thresholds trade false-positive and false-negative rates; they do not correct an infeasible optimization formulation.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.2 Classification Performance Evaluation"}]}]}, {"question_id": "CAPX-D5-Q006", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.2.3"], "topic": "Time-dependent predictive evaluation error", "section": "", "difficulty": "advanced", "stem": "A retailer randomly splits five years of weekly data to evaluate a one-week-ahead demand forecast. Observations from later years appear in training while earlier weeks appear in testing. The reported error is far better than field performance. What should the team do?", "correct_key": "C", "options": [{"key": "A", "text": "Increase the random test fraction and stratify by year, but continue mixing past and future weeks.", "is_correct": false, "rationale": "A larger random test set does not correct the temporal ordering problem.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.3 Performance Evaluation for Time-Dependent Data"}]}, {"key": "B", "text": "Fit once on all five years and report in-sample residuals by season and product category.", "is_correct": false, "rationale": "In-sample performance overestimates predictive performance and still does not mimic forecasting future periods.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}, {"key": "C", "text": "Use rolling-origin evaluation: train only on information available before each forecast date, predict a later period, repeat across periods, and summarize the resulting errors.", "is_correct": true, "rationale": "Correct. Rolling-horizon evaluation preserves time order and directly estimates one-step-ahead field performance over multiple periods.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.3 Performance Evaluation for Time-Dependent Data"}]}, {"key": "D", "text": "Convert weekly demand to ordered demand classes and use stratified random splitting across all years.", "is_correct": false, "rationale": "Changing the response type does not remove the underlying time dependency or future-to-past contamination.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.3 Performance Evaluation for Time-Dependent Data"}]}]}, {"question_id": "CAPX-D5-Q007", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.2.4"], "topic": "Prescriptive solver-formulation mismatch", "section": "", "difficulty": "advanced", "stem": "A pricing optimization model contains a nonlinear demand-response function, but the team sends the formulation unchanged to a linear-programming solver and accepts its output. What is the best correction?", "correct_key": "D", "options": [{"key": "A", "text": "Round the reported prices, check feasibility at those rounded values, and keep the result because the solver declared success.", "is_correct": false, "rationale": "Solver classes are not interchangeable; rounding does not correct a mismatch between nonlinear formulation and linear method.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}, {"key": "B", "text": "Replace the pricing objective with out-of-sample prediction accuracy, then select the linear formulation with the smallest forecast error.", "is_correct": false, "rationale": "Predictive accuracy is a model-evaluation statistic and does not represent the prescriptive pricing objective.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}, {"key": "C", "text": "Add historical price observations and refit demand coefficients, while leaving the nonlinear formulation in the linear solver.", "is_correct": false, "rationale": "More data may improve parameter estimates, but it does not resolve use of an inappropriate linear solution method.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}, {"key": "D", "text": "Write and characterize the variables, constraints, and objective; either derive and validate an equivalent linear reformulation or use an appropriate nonlinear method, then reverify the solution.", "is_correct": true, "rationale": "Correct. Solution technique must match the mathematical form; an LP package should not be applied outright to an NLP formulation.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}]}, {"question_id": "CAPX-D5-Q008", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.3.1"], "topic": "Interpreting diagnostic uncertainty", "section": "", "difficulty": "moderate", "stem": "A diagnostic analysis estimates that a process change increased throughput by 2 units per hour, with a 95% confidence interval from -1 to 5. Which interpretation is best?", "correct_key": "A", "options": [{"key": "A", "text": "The sample estimate is positive, but the interval includes zero, so the data do not establish a nonzero improvement at the corresponding confidence level.", "is_correct": true, "rationale": "Correct. An interval containing zero is compatible with no change, even though the point estimate is positive.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group I: Solution Techniques"}]}, {"key": "B", "text": "There is a 95% probability that the true increase is exactly 2 units per hour.", "is_correct": false, "rationale": "A confidence interval does not assign 95% probability to the single point estimate.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.9.3 Parameter Estimation with a Confidence Interval"}]}, {"key": "C", "text": "The change definitely reduced throughput because the negative lower endpoint overrides the positive point estimate and upper endpoint.", "is_correct": false, "rationale": "The interval spans both negative and positive values; it does not establish a reduction.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group I: Solution Techniques"}]}, {"key": "D", "text": "Uncertainty can be ignored because the point estimate is greater than zero.", "is_correct": false, "rationale": "The purpose of the interval is to represent uncertainty; relying only on the point estimate overstates the evidence.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.9.3 Parameter Estimation with a Confidence Interval"}]}]}, {"question_id": "CAPX-D5-Q009", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.3.2"], "topic": "Ensemble method selection", "section": "", "difficulty": "advanced", "stem": "A set of individual decision trees changes substantially when the training sample changes, producing high-variance predictions. The team wants an ensemble specifically aimed at reducing that variance. Which approach is most appropriate?", "correct_key": "B", "options": [{"key": "A", "text": "Boosting that repeatedly increases weight on previously misclassified observations, because its primary role is reducing variance.", "is_correct": false, "rationale": "The ABOK characterizes boosting primarily as a bias-reduction sequence, not the most direct variance-reduction choice in this scenario.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.7 Ensemble Methods"}]}, {"key": "B", "text": "Bagging: fit many trees on bootstrap samples and average predictions or vote across classes.", "is_correct": true, "rationale": "Correct. Bagging and random forests fit the same algorithm to resampled data and tend to reduce model-error variance and improve generalization.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.7 Ensemble Methods"}]}, {"key": "C", "text": "Select the single deepest tree because purity of training leaves reduces variance.", "is_correct": false, "rationale": "Deep, pure trees are usually overfit and can increase sensitivity to the training sample.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.3 Classification and Regression Trees"}]}, {"key": "D", "text": "Stack the tree outputs using weights chosen on the same data used to fit every base tree, with no out-of-sample check.", "is_correct": false, "rationale": "Stacking can combine models, but choosing and judging it without an out-of-sample procedure risks optimistic performance and does not directly address the requested robust evaluation.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.7 Ensemble Methods"}]}]}, {"question_id": "CAPX-D5-Q010", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.3.3"], "topic": "Predictive-classifier output interpretation", "section": "", "difficulty": "advanced", "stem": "A fraud model outputs a probability for each transaction. Missing a fraud case costs far more than reviewing a legitimate transaction, and fraud is rare. How should the team interpret and operationalize the output?", "correct_key": "C", "options": [{"key": "A", "text": "Use 0.50 as the action threshold, report recall and false-positive rate there, and treat it as the neutral operating point.", "is_correct": false, "rationale": "Classification thresholds can and often should differ from 0.50, especially for rare events and asymmetric error costs.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.2 Classification Performance Evaluation"}]}, {"key": "B", "text": "Report accuracy and AUC on the holdout set, but do not quantify false-negative and false-positive business costs.", "is_correct": false, "rationale": "Overall accuracy can be misleading for rare positives and does not express the different costs of false negatives and false positives.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.2 Classification Performance Evaluation"}]}, {"key": "C", "text": "Choose a threshold using representative holdout results and the business costs of false negatives and false positives; report the confusion matrix, relevant rates, and expected cost at that threshold.", "is_correct": true, "rationale": "Correct. The probability must be converted to an action threshold that reflects the asymmetric real-world consequences.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.2 Classification Performance Evaluation"}]}, {"key": "D", "text": "Treat a 0.20 fraud probability as legitimate unless an investigator independently finds contradictory evidence, without setting a cost-based threshold.", "is_correct": false, "rationale": "A class probability represents uncertainty; it is not a guarantee, and action depends on the chosen cost-sensitive threshold.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.2 Classification Performance Evaluation"}]}]}, {"question_id": "CAPX-D5-Q011", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.3.4"], "topic": "Verification of a prescriptive solution", "section": "", "difficulty": "advanced", "stem": "An integer optimization solver reports a warehouse plan with objective value 12.4 million. Before presenting it as the recommended solution, what is the strongest verification?", "correct_key": "D", "options": [{"key": "A", "text": "Accept the plan after confirming the solver log says optimal and the run completed without warnings.", "is_correct": false, "rationale": "A solver status alone does not verify that data, units, constraints, implementation, and reported objective reflect the intended model.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.30.1 Verifying"}]}, {"key": "B", "text": "Compare the objective with last year's value and confirm the reported decisions are whole numbers.", "is_correct": false, "rationale": "An improved objective and integrality do not establish all resource feasibility, correct units, or faithful implementation.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.16.1 Linear Program"}]}, {"key": "C", "text": "Ask operations whether the plan looks usable and accept it if stakeholders recognize the recommended pattern.", "is_correct": false, "rationale": "Business acceptance is important but cannot replace technical verification that the model did what was intended.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "5.2.2 The Operations Research Project Methodology"}]}, {"key": "D", "text": "Verify representative model states and actions against intended behavior, confirm the plan satisfies whole-number and resource restrictions, and compare its value with a valid bound or benchmark.", "is_correct": true, "rationale": "Correct. Verification checks whether model actions behave as intended; integrality and resource limits establish admissibility, while bounds show how the candidate compares with the best possible value.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.30.1 Verifying"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.16.1 Linear Program"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.16.4 Relaxations and Bounds"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.16.5 Are We Finished Yet?"}]}]}, {"question_id": "CAPX-D5-Q012", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.3.5"], "topic": "Diagnosing biased model outcomes", "section": "", "difficulty": "advanced", "stem": "A public-service prioritization model has similar overall accuracy to its benchmark but consistently underallocates service to rural residents. Rural applicants are sparse in the training data, and several location features are proxies for income and access. What is the most plausible diagnosis?", "correct_key": "A", "options": [{"key": "A", "text": "Nonrepresentative training data and proxy features are producing subgroup error and inequitable allocation; assess subgroup performance, data coverage, and feature effects before use.", "is_correct": true, "rationale": "Correct. Overall accuracy can hide subgroup harm, and apparently neutral variables can reproduce structural differences or protected-class correlations.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "B", "text": "The model cannot be biased because it does not include a variable named 'rural.'", "is_correct": false, "rationale": "Omitting an explicit group label does not prevent correlated proxies or unrepresentative data from producing discriminatory effects.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "C", "text": "Overall accuracy proves the allocations are fair, so no further analysis is needed.", "is_correct": false, "rationale": "Aggregate predictive performance is not a fairness audit and can conceal systematic subgroup disparities.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "D", "text": "Increase model complexity without changing data or evaluation because complexity removes representation bias.", "is_correct": false, "rationale": "More complex models do not correct missing representation and may amplify patterns embedded in the data.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.4 Model Fidelity"}]}]}, {"question_id": "CAPX-D5-Q013", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.4.1"], "topic": "Predictive recalibration from client feedback", "section": "", "difficulty": "advanced", "stem": "Contact-center managers report that a weekly call-volume model is accurate most of the year but badly underpredicts holiday surges and became worse after a new product launch. What is the best response?", "correct_key": "B", "options": [{"key": "A", "text": "Raise every forecast by a fixed constant chosen from last holiday's average miss, and retain that adjustment for future weeks.", "is_correct": false, "rationale": "A global adjustment does not represent recurring holiday seasonality or the structural change associated with the launch.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.4 Time Series Forecasting"}]}, {"key": "B", "text": "Examine residuals by time, add or revise holiday and launch-related features, refit on current data, and validate with rolling horizons across multiple surge periods.", "is_correct": true, "rationale": "Correct. The concern points to omitted temporal effects and possible concept drift; revised features, current data, and time-respecting validation directly address both.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.6.4 Time Series Forecasting"}]}, {"key": "C", "text": "Stratify weeks by holiday status, randomly shuffle within strata, and use the resulting split for final validation.", "is_correct": false, "rationale": "Random shuffling breaks time order and can make performance look better than true future forecasting performance.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.3 Performance Evaluation for Time-Dependent Data"}]}, {"key": "D", "text": "Keep the model because annual error is stable, and handle holiday shortages through manual planner overrides.", "is_correct": false, "rationale": "Business use may make errors during peak periods disproportionately costly, so aggregate error alone can hide material failure.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.1 Regression Performance Evaluation"}]}]}, {"question_id": "CAPX-D5-Q014", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.4.2"], "topic": "Prescriptive calibration from client feedback", "section": "", "difficulty": "advanced", "stem": "A factory scheduler minimizes reported cost, but supervisors say its recommendations are infeasible because changeovers require 45 minutes and certain product sequences are prohibited. What should the analytics team do?", "correct_key": "C", "options": [{"key": "A", "text": "Ask supervisors to follow the mathematically optimal schedule and handle prohibited sequences manually during execution.", "is_correct": false, "rationale": "A recommendation that violates real operating rules is not actionable or valid for the business system.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.31.5 Model Solutions Require a Lot of Polish and Refinement Before They Can Directly Influence Policy"}]}, {"key": "B", "text": "Change report colors and add warnings for changeovers, without modifying the omitted process-time or sequence constraints.", "is_correct": false, "rationale": "Presentation changes do not repair omitted process times or prohibited transitions.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.11 Extensibility"}]}, {"key": "C", "text": "Confirm the operating rules with supervisors, add sequence and changeover-time variables or constraints with correct data, re-solve, and jointly validate feasibility and business cost.", "is_correct": true, "rationale": "Correct. Client feedback has exposed omitted constraints and data; iterative formulation and validation are needed before judging the revised recommendation.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.11 Extensibility"}]}, {"key": "D", "text": "Remove the most restrictive constraints and let supervisors repair any infeasible recommendations after the solver runs.", "is_correct": false, "rationale": "Removing real feasibility conditions may improve the reported objective while making the advice unachievable.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.6 With Different Methods"}]}]}, {"question_id": "CAPX-D5-Q015", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.5.1"], "topic": "Integrating predictive and prescriptive models", "section": "", "difficulty": "advanced", "stem": "A retailer combines a weekly demand forecast with an inventory optimizer. The forecast produces store-item distributions for 13 weeks, while the optimizer expects one monthly point estimate by region. What should the team do before integration?", "correct_key": "D", "options": [{"key": "A", "text": "Feed the weekly distributions directly into the monthly point-estimate fields and let the software coerce the values.", "is_correct": false, "rationale": "Automatic coercion hides incompatible grain, horizon, geography, and uncertainty assumptions.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.1 Model Formulation"}]}, {"key": "B", "text": "Discard forecast uncertainty, select the week with the highest demand, and repeat that value for every month and region.", "is_correct": false, "rationale": "This arbitrary transformation loses horizon alignment and may systematically overstate demand without representing the optimizer's decision context.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Data Considerations"}]}, {"key": "C", "text": "Run the models independently and compare their objective values as if they measure the same quantity.", "is_correct": false, "rationale": "Forecast error and optimization objective value are different constructs; independent runs do not resolve the interface between models.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5.1 Regression Performance Evaluation"}]}, {"key": "D", "text": "Define the interface data elements, indices, and units explicitly, reconcile the weekly store-item forecast with the optimizer's monthly regional input, and verify that the unified solution addresses both model components.", "is_correct": true, "rationale": "Correct. Model inputs need defined dimensions and units, and a federation of unlike model classes requires explicit verification that the combined solution satisfies each component's concerns.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.1 Model Formulation"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.11 Extensibility"}]}]}, {"question_id": "CAPX-D5-Q016", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X 5.6.1"], "topic": "Audience-appropriate communication of model limits", "section": "", "difficulty": "moderate", "stem": "An analytics team must communicate a demand model to executives, planners, and model maintainers. Which communication package is most appropriate?", "correct_key": "A", "options": [{"key": "A", "text": "A summary of impact and uncertainty; a planner guide to inputs, outputs, and actions; and technical documentation of data, assumptions, validation, limitations, and maintenance.", "is_correct": true, "rationale": "Correct. Different stakeholders need different depth, but all communications should preserve material assumptions, limitations, and decision context.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.31 Communicate with Stakeholders"}]}, {"key": "B", "text": "The full source code only, sent identically to every audience.", "is_correct": false, "rationale": "Source code alone does not explain business impact, operating use, or assumptions in the language needed by each stakeholder.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.2 Communication"}]}, {"key": "C", "text": "A one-page claim that the model is accurate, with assumptions and failure conditions omitted to avoid concern.", "is_correct": false, "rationale": "Recommendations must be stated with full regard to model limitations; omitting them can mislead decision-makers.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.4 Model Fidelity"}]}, {"key": "D", "text": "A coefficient table and p-values for executives, with no translation to operational decisions.", "is_correct": false, "rationale": "Technical statistics alone are less effective than a clear input-output-impact explanation for nontechnical decision-makers.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.2 Communication"}]}]}, {"question_id": "CAPX-D6-Q001", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.1.1"], "topic": "Business validation before deployment", "section": "", "difficulty": "advanced", "stem": "A replenishment model has passed technical tests and is estimated to reduce stock-outs by 12%. The sponsor asks whether to deploy enterprise-wide. What is the best business-validation step?", "correct_key": "C", "options": [{"key": "A", "text": "Approve enterprise rollout from the technical validation and modeled 12% estimate, then measure stock-outs and inventory effects after every location is live.", "is_correct": false, "rationale": "Technical evaluation yields only an estimated business benefit before operation; enterprise deployment would expose the whole organization before realized value is measured.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.21 CRISP-DM Phase 5: Evaluation"}]}, {"key": "B", "text": "Hold a technical review of forecast error and runtime; if both meet their thresholds, infer the stock-out benefit without a separate operational comparison.", "is_correct": false, "rationale": "Technical measures are useful, but successful models must also support and be evaluated against the sponsoring organization's business metrics.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.4 Metrics"}]}, {"key": "C", "text": "Run a representative controlled pilot, compare agreed stock-out, inventory, service, and process metrics with a credible baseline, report uncertainty and operational effects, and recommend whether to proceed.", "is_correct": true, "rationale": "Correct. A representative pilot connects technical performance to observable business outcomes and gives the sponsor evidence and uncertainty for a deployment decision.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.21 CRISP-DM Phase 5: Evaluation"}]}, {"key": "D", "text": "Ask analytics, inventory, and store managers to review example outputs and reach consensus, using their qualitative judgment instead of measured pilot results.", "is_correct": false, "rationale": "Collaborative stakeholder judgment is necessary, but it should act on evidence from agreed metrics rather than substitute for business validation.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.21 CRISP-DM Phase 5: Evaluation"}]}]}, {"question_id": "CAPX-D6-Q002", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.1.2"], "topic": "Ethical risk of a business use", "section": "", "difficulty": "moderate", "stem": "The same predictive platform could support four business uses. Which use presents the greatest risk of adverse ethical consequences and therefore demands the strongest oversight?", "correct_key": "D", "options": [{"key": "A", "text": "Recommending weekly cafeteria ingredient quantities, with a manager reviewing predicted waste and shortage levels before placing each order.", "is_correct": false, "rationale": "This use has operational consequences but generally affects people's rights and life opportunities less directly than a high-stakes eligibility decision.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "B", "text": "Forecasting spare-part consumption for preventive maintenance, with technicians reviewing the quantities before maintenance work orders are scheduled.", "is_correct": false, "rationale": "This can create business risk, but it is less morally fraught than an automated decision determining access to an essential benefit.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "C", "text": "Ranking submitted product images for an internal design review, with designers retaining authority over the final portfolio selection.", "is_correct": false, "rationale": "The use may warrant quality and explanation controls, but its direct consequences for people's life opportunities are comparatively limited.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "D", "text": "Automatically denying access to housing assistance using applicant-level risk scores, with no explanation or appeal path.", "is_correct": true, "rationale": "Correct. A consequential automated eligibility decision can amplify data or proxy bias and directly affect a person's life; explanation, responsibility, auditability, and fairness are essential.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}]}, {"question_id": "CAPX-D6-Q003", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.2.1"], "topic": "Nontechnical business-validation summary", "section": "", "difficulty": "moderate", "stem": "A chief operating officer needs a two-minute summary of a technically complex model-validation report. Which summary is most appropriate?", "correct_key": "A", "options": [{"key": "A", "text": "State the decision, key inputs and output, expected impact versus baseline, major uncertainty and limits, material risks, and recommended next action, using a simple graphic where helpful.", "is_correct": true, "rationale": "Correct. A nontechnical summary should connect inputs and outputs to business effect and action while preserving the most decision-relevant uncertainty and limitations.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.2 Communication"}]}, {"key": "B", "text": "Summarize the statistically significant coefficients, solver settings, and p-values, then direct the executive to the full report without translating them into the operating decision.", "is_correct": false, "rationale": "Technical details without a decision-oriented translation are unlikely to create understanding or confidence for an executive audience.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.2 Communication"}]}, {"key": "C", "text": "Report that validation targets were met, defer uncertainty and limitations to a technical appendix, and recommend deployment without discussing unfavorable findings or alternatives.", "is_correct": false, "rationale": "Communication should be transparent about issues, options, and recommendations; burying material findings undermines trust and sound decisions.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.2 Communication"}]}, {"key": "D", "text": "Demonstrate the source code and architecture, then ask the executive to infer the business impact, limitations, and next action from the technical walkthrough.", "is_correct": false, "rationale": "A technical walkthrough is not a substitute for an audience-appropriate explanation of purpose, evidence, impact, and limitations.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.31 Communicate with Stakeholders"}]}]}, {"question_id": "CAPX-D6-Q004", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.3.1"], "topic": "Stakeholder alignment for deployment", "section": "", "difficulty": "advanced", "stem": "A new workforce-planning solution changes approval rights, staffing routines, and performance measures across operations, finance, and human resources. What is needed before the sponsor authorizes deployment?", "correct_key": "B", "options": [{"key": "A", "text": "Have the data-science manager certify technical completion and ask each affected function to resolve ownership, workflow, and training questions during rollout.", "is_correct": false, "rationale": "Technical completion does not replace a jointly agreed plan among the business groups whose roles, metrics, and processes will change.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.21 CRISP-DM Phase 5: Evaluation"}]}, {"key": "B", "text": "Create a shared impact assessment of changed decisions and workflows, owners, benefits, resources, training, risks, success measures, rollout, and fallback; record the affected stakeholders' decisions.", "is_correct": true, "rationale": "Correct. Stakeholders can align only when they understand the operational consequences, ownership, value, risks, and criteria for proceeding or reversing course.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.1 Documentation"}]}, {"key": "C", "text": "Secure sign-off on technical accuracy and projected savings, while postponing ownership, changed workflows, training, maintenance resources, and fallback decisions until implementation.", "is_correct": false, "rationale": "Accuracy and projected value are useful, but the documentation must also align business needs with implementation and ongoing resource responsibilities.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.1 Documentation"}]}, {"key": "D", "text": "Begin a limited rollout under sponsor authority and use early adoption results to decide which stakeholder agreements and cross-functional role changes are necessary.", "is_correct": false, "rationale": "Deployment evidence can inform refinement, but affected stakeholders should jointly decide the plan before implementation rather than after adoption problems appear.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.21 CRISP-DM Phase 5: Evaluation"}]}]}, {"question_id": "CAPX-D6-Q005", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.4.1"], "topic": "Production documentation for business users", "section": "", "difficulty": "moderate", "stem": "A forecasting system is moving into daily use by inventory planners. Which documentation is most appropriate for a business user?", "correct_key": "C", "options": [{"key": "A", "text": "A mathematically complete model manual with algorithm assumptions and derivations, but no task-based guidance, realistic exercises, or check of user understanding.", "is_correct": false, "rationale": "Theory may help some users, but effective training must explain model use in manageable units and include practice or a way to demonstrate mastery.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.31.1 Training"}]}, {"key": "B", "text": "A technical deployment binder containing production architecture, interfaces, and test-plan details, but no guidance on how planners use or interpret the forecasts.", "is_correct": false, "rationale": "Production requirements help implementers, but a business user also needs training in using, interpreting, and explaining the model outputs.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.23 Deployment of the Analytics Model (Up to Delivery)"}]}, {"key": "C", "text": "A planner-focused guide that explains how to use and interpret model outputs, breaks the workflow into manageable steps, includes realistic practice scenarios, and provides a way to demonstrate mastery.", "is_correct": true, "rationale": "Correct. ABOK places model-use and output-interpretation knowledge in training materials and recommends manageable learning units, practice, and a method to verify user mastery.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.23 Deployment of the Analytics Model (Up to Delivery)"}]}, {"key": "D", "text": "A concise launch guide describing expected benefits and the normal workflow, but presenting forecasts as exact and omitting limitations, practice scenarios, and mastery checks.", "is_correct": false, "rationale": "A usable guide should not overstate model fidelity, and training should provide practice and a way to establish that users understand the model.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.4 Model Fidelity"}]}]}, {"question_id": "CAPX-D6-Q006", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.4.2"], "topic": "Reusable model and report documentation", "section": "", "difficulty": "advanced", "stem": "A credit-risk solution may be reused next year after products, regulations, and customer behavior change. Which documentation package best supports safe reuse?", "correct_key": "D", "options": [{"key": "A", "text": "A dated dashboard export showing current scores and charts, plus an approval note, but no definitions, data vintage, provenance, assumptions, or validation conditions.", "is_correct": false, "rationale": "A dashboard snapshot does not establish the data vintage and provenance that should accompany each model instance or the conditions for safe reuse.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.30.6 Data Vintage and Provenance"}]}, {"key": "B", "text": "A coefficient file and code snapshot with feature names, but no units, population, model assumptions, validation evidence, limitations, or criteria for reassessment.", "is_correct": false, "rationale": "Coefficients and code cannot be safely reapplied without defined data elements, units, model logic, operating assumptions, and applicable evidence.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.27.1 Model Formulation"}]}, {"key": "C", "text": "A validation summary with headline metrics and sign-off date, but without validation data, thresholds, known limits, or the circumstances in which the results apply.", "is_correct": false, "rationale": "Validation provides contextual assurance rather than proof of permanent alignment with reality; the evidence and applicable conditions must be preserved.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.30.2 Validating"}]}, {"key": "D", "text": "Versioned documentation of purpose, population, data and provenance, features and units, model logic, assumptions, tests, known limitations, monitoring, and change and revalidation procedures.", "is_correct": true, "rationale": "Correct. Reuse after changed circumstances requires a reproducible formulation plus evidence, limits, and explicit triggers for reassessment.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.1 Documentation"}]}]}, {"question_id": "CAPX-D6-Q007", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.5.1"], "topic": "Layered deployment testing", "section": "", "difficulty": "moderate", "stem": "A real-time scoring service passed several happy-path unit tests. Which additional test plan best supports deployment readiness?", "correct_key": "A", "options": [{"key": "A", "text": "Test components over the full input range, exercise end-to-end data-to-decision scenarios and interfaces, then stress volume, latency, failure, and recovery behavior against acceptance criteria.", "is_correct": true, "rationale": "Correct. Deployment testing should progress from component behavior through end-to-end operation and stress conditions across the full input range.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.3 Testing"}]}, {"key": "B", "text": "Expand happy-path unit tests to every component and validate interface schemas on sample messages, but omit end-to-end failures, production volume, and recovery behavior.", "is_correct": false, "rationale": "Broader unit coverage is useful, but it does not establish end-to-end integration or performance and recovery under stressful conditions.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.3 Testing"}]}, {"key": "C", "text": "Use a large randomly generated test set spanning numeric ranges, but do not include representative starting states, production dependencies, malformed records, or business scenarios.", "is_correct": false, "rationale": "Volume and range alone do not substitute for representative sample data that reveal how the implemented model behaves in practice.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.30.4 Sample Data"}]}, {"key": "D", "text": "Benchmark average runtime on production-sized hardware and confirm target latency, but skip overload, unusually complex cases, downstream failure, and recovery scenarios.", "is_correct": false, "rationale": "A latency benchmark is useful, but stress testing must also examine large or complex conditions and whether performance degrades at the limits.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.3 Testing"}]}]}, {"question_id": "CAPX-D6-Q008", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.5.1"], "topic": "Shadow-mode production validation", "section": "", "difficulty": "advanced", "stem": "A utility wants to replace a legacy load forecast used in daily planning. A wrong forecast could cause costly operating decisions. Which final pre-cutover test is most appropriate?", "correct_key": "B", "options": [{"key": "A", "text": "Compare new and legacy forecasts for one recent month, perform a single cutover, and rely on quarterly monitoring to identify interface or performance problems afterward.", "is_correct": false, "rationale": "A limited comparison followed by immediate cutover omits the carefully staged testing needed before live operating decisions depend on the new system.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.23 Deployment of the Analytics Model (Up to Delivery)"}]}, {"key": "B", "text": "Run shadow mode on synchronized production-like feeds; compare forecasts, latency, exceptions, and downstream calculations; exercise failures and rollback; cut over only after acceptance criteria are met.", "is_correct": true, "rationale": "Correct. Shadow operation tests realistic end-to-end behavior and risk controls without letting unproven outputs drive live decisions.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.3 Testing"}]}, {"key": "C", "text": "Run both systems on synchronized feeds and compare forecast accuracy, but omit latency, exceptions, downstream calculations, failure recovery, and rollback readiness from acceptance.", "is_correct": false, "rationale": "A forecast comparison is useful, but implementation support must also address model runtime, interactions with the wider architecture, and final testing.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.23 Deployment of the Analytics Model (Up to Delivery)"}]}, {"key": "D", "text": "Test several hand-created average and peak days and confirm their forecasts with planners, but do not exercise the full input range, extreme complexity, or recovery behavior.", "is_correct": false, "rationale": "Several cases improve coverage, but deployment testing should span the full input range and stressful or complex situations, including degraded performance.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.3 Testing"}]}]}, {"question_id": "CAPX-D6-Q009", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.5.2"], "topic": "Analytics professional deployment responsibilities", "section": "", "difficulty": "moderate", "stem": "Enterprise IT owns implementation of a model the analytics team developed. During integration, production data cause unexpected errors and runtime exceeds the service limit. What is the analytics professional's responsibility?", "correct_key": "C", "options": [{"key": "A", "text": "Transfer code and known issues to IT, remain available for scheduled questions, and let IT independently diagnose all production data and model-runtime behavior.", "is_correct": false, "rationale": "A passive handoff is insufficient because the analytics team's model and data knowledge remains necessary through troubleshooting, final testing, and operational handoff.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.23 Deployment of the Analytics Model (Up to Delivery)"}]}, {"key": "B", "text": "Have the analytics team take direct control of the enterprise release and infrastructure until runtime targets are met, then return ownership to IT.", "is_correct": false, "rationale": "When IT owns implementation, the analytics team supplies essential model expertise in a support role rather than displacing the implementation owner.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.23 Deployment of the Analytics Model (Up to Delivery)"}]}, {"key": "C", "text": "Work with IT to diagnose model-specific data and runtime behavior, define tests and expected outputs, make approved adaptations, document changes, and support final testing and handoff.", "is_correct": true, "rationale": "Correct. The analytics professional supplies specialized knowledge while collaborating within the deployment ownership structure.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.23 Deployment of the Analytics Model (Up to Delivery)"}]}, {"key": "D", "text": "Patch model parameters with IT to meet runtime, deploy through an emergency change process, and defer regression testing and documentation until the next scheduled release.", "is_correct": false, "rationale": "An approved change path does not replace testing and updated documentation needed to show the revised model functions as designed.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.1 Documentation"}]}]}, {"question_id": "CAPX-D6-Q010", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X 6.6.1"], "topic": "Synchronizing production data sources", "section": "", "difficulty": "advanced", "stem": "A daily credit-risk score joins account balances, payment events, and customer status from three systems that refresh at different times. During deployment tests, scores change depending on query order. Which synchronization rule is best?", "correct_key": "D", "options": [{"key": "A", "text": "For each source, select the most recently loaded record and record its load time, even when business effective times and the scoring cutoff differ.", "is_correct": false, "rationale": "Load time alone does not ensure that records from multiple sources are time-stamped and aligned to the same business period.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}]}, {"key": "B", "text": "Align the two highest-volume sources to a common batch date, then carry forward the latest customer-status record regardless of its vintage.", "is_correct": false, "rationale": "All sources on which the model depends require current, accurate data; source volume is not a basis for omitting temporal alignment.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.28 Rules for Data Use"}]}, {"key": "C", "text": "Cache the first successful response from each source and log query order, without requiring the records to share a documented business-time cutoff.", "is_correct": false, "rationale": "Run-level reproducibility is insufficient when the exact vintage and provenance of the data used by the model are not aligned and displayed.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.30.6 Data Vintage and Provenance"}]}, {"key": "D", "text": "Use a documented scoring cutoff, align time-stamped records from all three sources to that cutoff, and record and display the exact vintage and provenance used for each score.", "is_correct": true, "rationale": "Correct. Time stamps support temporal alignment across sources, and ABOK requires the vintage and provenance of every model instance to be established and shown with its outputs.", "citations": [{"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "2.2.3 Task 3: Prepare the Data (see also Chapter 4 )"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.30.6 Data Vintage and Provenance"}]}]}, {"question_id": "CAPX-D7-Q001", "revision": 1, "status": "eligible", "domain": "VII", "objectives": ["CAP-X 7.1.1"], "topic": "Factors affecting performance over time", "section": "", "difficulty": "advanced", "stem": "Six months after launch, a churn model's overall score distribution is stable, but retention campaign lift is falling. What monitoring view is most likely to reveal the cause?", "correct_key": "D", "options": [{"key": "A", "text": "Monitor job completion, latency, and scoring exceptions each day, and investigate business lift only when one of those operational measures triggers an alert.", "is_correct": false, "rationale": "Operational execution matters, but job health alone cannot reveal changed data relationships or whether the model's business effect is degrading.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.3.9 Model Implementation"}]}, {"key": "B", "text": "Monitor mean predicted probability and score volume by segment; if both remain stable, assume the underlying relationships and campaign response are also stable.", "is_correct": false, "rationale": "Stable aggregate or segment score summaries can coexist with changing predictor relationships and deteriorating model usefulness, which require direct performance monitoring.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.24 Post-deployment Activities (Domain VI: Model Life Cycle Management)"}]}, {"key": "C", "text": "Compare the current score distribution with the original test-set AUC and recalibrate only when both indicators move in the same unfavorable direction.", "is_correct": false, "rationale": "The original estimate and current score distribution do not establish that present data relationships or realized business response remain unchanged.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.3.9 Model Implementation"}]}, {"key": "D", "text": "Track data and relationship changes, current model performance, operational execution, and realized campaign lift; report degradation and investigate recalibration when action thresholds are reached.", "is_correct": true, "rationale": "Correct. Solution performance can degrade because data, relationships, processes, or the intervention itself changes, even when an aggregate score statistic appears stable.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.24 Post-deployment Activities (Domain VI: Model Life Cycle Management)"}]}]}, {"question_id": "CAPX-D7-Q002", "revision": 1, "status": "eligible", "domain": "VII", "objectives": ["CAP-X 7.2.1"], "topic": "Recalibration opportunity and risk", "section": "", "difficulty": "advanced", "stem": "A forecasting model's error has risen for three consecutive months after customer behavior shifted. New labeled outcomes are now available. What is the safest recalibration plan?", "correct_key": "A", "options": [{"key": "A", "text": "Investigate the changed data and relationships, recalibrate with current outcomes, evaluate the revised forecast on later data not used for fitting, and report the comparison to responsible managers before replacement.", "is_correct": true, "rationale": "Correct. ABOK expects monitoring to trigger recalibration when relationships change, management reporting of degradation, and out-of-sample evaluation rather than a training-set claim.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.24 Post-deployment Activities (Domain VI: Model Life Cycle Management)"}, {"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}, {"key": "B", "text": "Retrain on all newly labeled data, replace the model if in-sample error improves, and monitor it closely after deployment instead of reserving an evaluation period.", "is_correct": false, "rationale": "In-sample improvement overestimates predictive performance; monitoring after replacement does not recover the missing independent evaluation before the decision.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.5 Predictive Performance Evaluation"}]}, {"key": "C", "text": "Tune repeatedly on the current production evaluation window until the desired result appears, then report that same result as independent evidence.", "is_correct": false, "rationale": "Using the same outcomes for repeated tuning and final evaluation destroys the independence of the performance estimate.", "citations": [{"source": "CH7 Machine learning PDF", "url": "https://drive.google.com/file/d/1y67xnqWTD_-xHW1t_AneCyFB8mzDkWDG/view", "locator": "7.4.2 Model Fitting: Balancing Bias and Variance"}]}, {"key": "D", "text": "Keep the current model until the annual review to preserve coefficient comparability; document the rising error but postpone recalibration despite the behavior shift.", "is_correct": false, "rationale": "When underlying relationships evolve, delaying recalibration can allow forecast errors to keep growing; maintenance should respond when monitoring reaches an action level.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.24 Post-deployment Activities (Domain VI: Model Life Cycle Management)"}]}]}, {"question_id": "CAPX-D7-Q003", "revision": 1, "status": "eligible", "domain": "VII", "objectives": ["CAP-X 7.2.2"], "topic": "Alternative solutions after external change", "section": "", "difficulty": "advanced", "stem": "A routing optimizer was built when a downtown corridor was open. A new regulation permanently prohibits commercial vehicles there and changes driver-hour rules. What is the best lifecycle response?", "correct_key": "B", "options": [{"key": "A", "text": "Retain the optimizer but add an operator checklist requiring drivers to reject prohibited or infeasible routes manually; monitor exceptions before deciding whether to rebuild.", "is_correct": false, "rationale": "Human screening reduces some immediate harm, but recommendations that omit permanent legal and feasibility rules are not themselves actionable or legal.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.31.5 Model Solutions Require a Lot of Polish and Refinement Before They Can Directly Influence Policy"}]}, {"key": "B", "text": "Return with stakeholders to the business and data assumptions, encode the new legal constraints, and compare a revised optimizer with alternative approaches for legality, robustness, service, and cost before jointly selecting the next plan.", "is_correct": true, "rationale": "Correct. Evaluation findings can require reframing and alternative modeling approaches selected collaboratively; any proposed solution must also be legal, robust, and actionable under current conditions.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.21 CRISP-DM Phase 5: Evaluation"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.31.5 Model Solutions Require a Lot of Polish and Refinement Before They Can Directly Influence Policy"}]}, {"key": "C", "text": "Update dashboard warnings and compliance text, keep the original road network and constraints, and require supervisors to catch violations during daily review.", "is_correct": false, "rationale": "Communication and review do not repair the underlying formulation when its constraints no longer represent the legal feasible region.", "citations": [{"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Group II: Solution Techniques"}]}, {"key": "D", "text": "Refit travel times using a larger pre-regulation history, keep the formulation unchanged, and compare service and cost before deciding whether explicit legal constraints are necessary.", "is_correct": false, "rationale": "More historical observations do not make obsolete restrictions current; a model depends on the currency and accuracy of all required data and rules.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.28 Rules for Data Use"}]}]}, {"question_id": "CAPX-D7-Q004", "revision": 1, "status": "eligible", "domain": "VII", "objectives": ["CAP-X 7.3.1"], "topic": "Role-based business-user training", "section": "", "difficulty": "moderate", "stem": "A decision-support system will be used by frontline operators, supervisors, executives, and technical support staff. What training design is best?", "correct_key": "C", "options": [{"key": "A", "text": "Provide every role with a common model overview and source-code demonstration, then use the same interpretation quiz to confirm baseline understanding.", "is_correct": false, "rationale": "A shared overview can help, but effective training must explain the model to the people responsible for using it in manageable, relevant units.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.31.1 Training"}]}, {"key": "B", "text": "Train executives and supervisors on KPIs and overrides, then have them cascade informal guidance to frontline users and technical support after launch.", "is_correct": false, "rationale": "Leadership training is insufficient because the people who use and interpret model outputs also need prepared materials, practice, and demonstrated mastery.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.23 Deployment of the Analytics Model (Up to Delivery)"}]}, {"key": "C", "text": "Tailor training: operators learn workflow and exceptions; supervisors, oversight and escalation; executives, value and risk; technical staff, diagnostics and maintenance; each role practices and demonstrates mastery.", "is_correct": true, "rationale": "Correct. Role-specific training connects each audience to the model controls, theory, interpretation, and responsibilities it actually needs.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.23 Deployment of the Analytics Model (Up to Delivery)"}]}, {"key": "D", "text": "Give each role written job aids and sandbox access, but no guided practice or mastery check; address interpretation questions during production use.", "is_correct": false, "rationale": "Materials and sandbox access help, but ABOK also recommends practice scenarios and a method by which users demonstrate sufficient mastery.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.31.1 Training"}]}]}, {"question_id": "CAPX-D7-Q005", "revision": 1, "status": "eligible", "domain": "VII", "objectives": ["CAP-X 7.4.1"], "topic": "Attributable lifecycle benefits and costs", "section": "", "difficulty": "advanced", "stem": "One year after a demand-forecasting solution launched, revenue rose 8%, but the economy, assortment, pricing, and promotions also changed. Which analysis best validates the ongoing business case?", "correct_key": "D", "options": [{"key": "A", "text": "Adjust the before-and-after revenue trend for seasonality, then attribute the remaining increase to the model without examining other concurrent business and economic changes.", "is_correct": false, "rationale": "A time adjustment alone does not separate the model's effect from the many business, competitive, economic, and political factors affecting results.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.24 Post-deployment Activities (Domain VI: Model Life Cycle Management)"}]}, {"key": "B", "text": "Evaluate revenue and profit changes but omit the ongoing model-maintenance resources because those activities were approved and budgeted before launch.", "is_correct": false, "rationale": "Prior approval does not eliminate the ongoing maintenance activity and resources required to sustain a model over its useful life.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.24 Post-deployment Activities (Domain VI: Model Life Cycle Management)"}]}, {"key": "C", "text": "Use current forecast error and system uptime as proxies for value, and treat improved technical performance as sufficient without remeasuring inventory, service, revenue, or profit.", "is_correct": false, "rationale": "Technical performance is not the full business case; model operation should be linked to the organization's operational and financial metrics.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.24 Post-deployment Activities (Domain VI: Model Life Cycle Management)"}]}, {"key": "D", "text": "At appropriate intervals, account for concurrent business and economic changes, link model operation to inventory, stock-out, revenue, and profit results, include ongoing maintenance resources, and report uncertainty.", "is_correct": true, "rationale": "Correct. This reassesses business benefit using relevant metrics while recognizing other influences and the continuing resources needed to monitor and maintain the solution.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.2.24 Post-deployment Activities (Domain VI: Model Life Cycle Management)"}]}]}, {"question_id": "CAPX-D7-Q006", "revision": 1, "status": "eligible", "domain": "VII", "objectives": ["CAP-X 7.5.1"], "topic": "Latent ethical side effects", "section": "", "difficulty": "advanced", "stem": "A city allocates mobile health clinics using predicted demand derived largely from smartphone app activity. No race or disability field is used, and aggregate utilization improves. Which outcome is the clearest hidden ethical warning?", "correct_key": "A", "options": [{"key": "A", "text": "Neighborhoods with many older, low-income, or disabled residents receive fewer visits because their needs are less visible in app data, even though actual unmet need remains high.", "is_correct": true, "rationale": "Correct. Nonrepresentative digital data can make groups invisible and create inequitable allocation without an explicit protected attribute appearing in the model.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "B", "text": "Clinic allocations remain unchanged across demographic groups, but the scheduling job takes ten seconds longer in every neighborhood during peak hours.", "is_correct": false, "rationale": "Runtime is an operational issue, not by itself evidence of a discriminatory allocation or another adverse societal consequence.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "C", "text": "Visits shift toward high-need neighborhoods after community review, while the revised dashboard color palette lowers executive satisfaction with the presentation.", "is_correct": false, "rationale": "Aesthetic dissatisfaction is not comparable to the systematic exclusion of public-service needs caused by unrepresentative digital data.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}, {"key": "D", "text": "Overall prediction error and aggregate utilization both improve after recalibration, with no observed change in neighborhood-level allocation or unmet need.", "is_correct": false, "rationale": "Aggregate improvement does not itself show an ethical harm; the scenario specifies no adverse allocation effect, though subgroup monitoring remains prudent.", "citations": [{"source": "CH1 Introduction PDF", "url": "https://drive.google.com/file/d/1xpZ78WiaYsZ4F6J44ahMoqrmN2RYGV3x/view", "locator": "1.5 Ethical Implications"}]}]}, {"question_id": "CAPX-D7-Q007", "revision": 1, "status": "eligible", "domain": "VII", "objectives": ["CAP-X 7.6.1"], "topic": "Lifecycle documentation and monitoring", "section": "", "difficulty": "advanced", "stem": "An audit finds that a production model has been recalibrated three times, but the team cannot reconstruct which data, thresholds, tests, or approvals were used. What documentation practice should replace this process?", "correct_key": "B", "options": [{"key": "A", "text": "Retain the latest model binary, threshold, and headline metric, and discard earlier release packages after each new version passes its production test.", "is_correct": false, "rationale": "Discarding earlier data evolutions and decisions prevents the indexing and provenance tracking needed to reconstruct what each release used.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.28.12 Multiple Data Evolutions"}]}, {"key": "B", "text": "Maintain an indexed lifecycle record for every recalibration, preserving its model settings, data vintage and provenance, test evidence, decision and approval notes, and update the shared deployment documentation as understanding and maintenance needs evolve.", "is_correct": true, "rationale": "Correct. ABOK calls for indexed, provenance-aware data evolutions, vintage recorded for every model instance, organic documentation updated through deployment, and written records of conclusions reached.", "citations": [{"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.28.12 Multiple Data Evolutions"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "6.30.6 Data Vintage and Provenance"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.1 Documentation"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.2 Communication"}]}, {"key": "C", "text": "Keep a formal change log for releases that improve the headline metric, but summarize failed experiments verbally and retain only approved production artifacts.", "is_correct": false, "rationale": "Selective written records obscure issues and rejected decisions; transparent communication should describe problems, options, and conclusions rather than only successes.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.2 Communication"}]}, {"key": "D", "text": "Record each recalibration in meeting minutes with names and dates, then rely on participants to reconstruct the data, tests, and rationale if an incident occurs.", "is_correct": false, "rationale": "Meeting minutes help, but they do not replace written documentation of the conclusions and evolving model evidence needed for reliable traceability.", "citations": [{"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "8.3.2 Communication"}]}]}, {"question_id": "CAPX-D1-Q101", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X Domain I"], "topic": "Scope and constraints", "section": "Business Problem Framing", "difficulty": "moderate", "stem": "A vice president asks analytics to 'optimize the entire supply network this quarter.' Transportation, inventory, and supplier-capacity data are incomplete for two regions, and a labor contract freeze blocks changing shift patterns until next year. What should the team do first?", "correct_key": "C", "options": [{"key": "A", "text": "Accept the enterprise-wide scope and assemble every available supply-chain table so modeling can start immediately.", "is_correct": false, "rationale": "An unconstrained slogan is not a problem statement. Known policy and data limits must be written into scope before data wrangling becomes the project.", "citations": [{"source": "CAP-Expert Domain I", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Evaluate the scope of the business problem"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Target problem and constraints"}]}, {"key": "B", "text": "Refuse the request because incomplete data means no analytics work is possible.", "is_correct": false, "rationale": "Data gaps are constraints to disclose and manage. Scope can shrink to a decision the current data and contract allow.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Identify needed and available data"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Fitness for use"}]}, {"key": "C", "text": "Rewrite the request as a time-bounded decision with explicit geographies, frozen labor rules, success metrics, and sponsor-accepted data gaps.", "is_correct": true, "rationale": "Domain I requires a usable business problem: outcome, scope, constraints, and measures. Contract and data limits belong in that statement before methods are chosen.", "citations": [{"source": "CAP-Expert Domain I", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Understanding the business problem and evaluating its scope"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Getting started with the target problem"}]}, {"key": "D", "text": "Select a network-optimization solver first so the scope discussion has a technical anchor.", "is_correct": false, "rationale": "Methodology selection is Domain IV and follows a framed problem. A solver does not define the decision, horizon, or constraint set.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Methodology selection follows framing"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Methodology selection"}]}]}, {"question_id": "CAPX-D1-Q102", "revision": 1, "status": "eligible", "domain": "I", "objectives": ["CAP-X Domain I"], "topic": "Conflicting success measures", "section": "Business Problem Framing", "difficulty": "advanced", "stem": "Finance wants the project scored on contribution margin. Operations wants it scored on on-time fill rate. Both groups can block deployment. The sponsor says 'just pick one KPI so we can start.' What is the most appropriate response?", "correct_key": "B", "options": [{"key": "A", "text": "Adopt contribution margin because finance controls the budget.", "is_correct": false, "rationale": "Budget authority is not identical to the decision the model must support. Ignoring operations produces a metric operators will not use.", "citations": [{"source": "CAP-Expert Domain I", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Stakeholders and problem ownership"}, {"source": "INFORMS Analytics Framework", "url": "https://drive.google.com/file/d/14iRGcKL7mu7fm6XFcx3NzRVfGDH01kzY/view", "locator": "Business problem framing tasks"}]}, {"key": "B", "text": "Document both outcomes, how they conflict, the decision each would change, and a sponsor-approved primary measure plus a monitored constraint.", "is_correct": true, "rationale": "Expert framing records the trade-off instead of hiding it. One primary decision metric plus a watched constraint keeps deployment politically and operationally viable.", "citations": [{"source": "CAP-Expert Domain I", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Success measures and scope"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Stakeholders and target problem"}]}, {"key": "C", "text": "Build two independent models and let each function deploy its own score.", "is_correct": false, "rationale": "Two unreconciled production scores encode the conflict and leave no single lifecycle owner.", "citations": [{"source": "CAP-Expert Domain VII", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Lifecycle ownership of a solution"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Deployment and life cycle"}]}, {"key": "D", "text": "Replace both KPIs with a model-fit statistic so the debate becomes technical.", "is_correct": false, "rationale": "Fit statistics are not business outcomes and cannot settle a value conflict between margin and service.", "citations": [{"source": "CAP-Expert Domain I vs V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Business measures precede model-quality measures"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Communicating model findings"}]}]}, {"question_id": "CAPX-D2-Q101", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X Domain II"], "topic": "Translating a business question into an analytics problem", "section": "Analytics Problem Framing", "difficulty": "moderate", "stem": "A retailer wants to 'know which stores will miss plan next month' so regional managers can pre-position inventory. Which statement is the best analytics-problem framing?", "correct_key": "A", "options": [{"key": "A", "text": "Predict, at store-SKU-week grain, P(miss plan) and expected unit shortfall in time for a weekly replenishment decision, subject to current lead times.", "is_correct": true, "rationale": "A good analytics frame names the decision, grain, output, horizon, and operating constraint. That is Domain II, not a restatement of the slogan.", "citations": [{"source": "CAP-Expert Domain II", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Frame the business question as an analytics problem"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "From business question to analytics problem"}]}, {"key": "B", "text": "Cluster stores on last year's sales so similar stores can share a single forecast.", "is_correct": false, "rationale": "Clustering may be a later method. It does not define the prediction target, decision, or timing the managers need.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Methods are chosen after the analytics problem is stated"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Methodology selection"}]}, {"key": "C", "text": "Report last month's miss-plan rate by region as the analytics solution.", "is_correct": false, "rationale": "A rear-view report does not support a next-month pre-positioning decision.", "citations": [{"source": "CAP-Expert Domain II", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Analytics outputs must serve the stated decision"}, {"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "Descriptive vs predictive purpose"}]}, {"key": "D", "text": "Wait until a complete SKU master exists in every region before framing the problem.", "is_correct": false, "rationale": "Data completeness is assessed inside the framed problem. Framing first tells you which completeness gaps actually matter.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Identify data needed after the analytics question is framed"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Data requirements follow the question"}]}]}, {"question_id": "CAPX-D2-Q102", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X Domain II"], "topic": "Assumptions and reformulation", "section": "Analytics Problem Framing", "difficulty": "advanced", "stem": "An analytics problem is framed as a linear program that assumes demand is known. Midway through scoping, demand owners say next-quarter volume is highly uncertain and leadership will not lock a single number. What should the team do?", "correct_key": "D", "options": [{"key": "A", "text": "Keep the LP and replace demand with last year's actuals so the math stays tractable.", "is_correct": false, "rationale": "Silent substitution of a stale point estimate hides the uncertainty the decision makers just declared material.", "citations": [{"source": "CAP-Expert Domain II", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "State assumptions and reformulate when they fail"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Prescriptive models and uncertain inputs"}]}, {"key": "B", "text": "Abandon analytics because uncertainty means optimization is invalid.", "is_correct": false, "rationale": "Uncertainty changes the formulation; it does not cancel the decision. Stochastic, robust, or scenario formulations exist for this case.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Select methods that match the problem structure"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Stochastic and robust alternatives"}]}, {"key": "C", "text": "Fit a demand-forecast model and treat its point forecast as certain inside the original LP.", "is_correct": false, "rationale": "A point forecast is still one number. If leadership will not lock a single volume, the analytics problem itself must carry uncertainty into the recommendation.", "citations": [{"source": "CAP-Expert Domain II", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Outputs must match how the decision will be used"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Communicating uncertainty"}]}, {"key": "D", "text": "Reformulate: treat demand as uncertain, define scenarios or a distribution with the demand owners, and change the recommendation from one plan to a policy or robust plan they can act on.", "is_correct": true, "rationale": "Domain II includes restating the analytics problem when a governing assumption dies. The output type should match a decision under uncertainty.", "citations": [{"source": "CAP-Expert Domain II", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Reformulate the analytics problem as understanding changes"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Analytics problem framing and assumptions"}]}]}, {"question_id": "CAPX-D2-Q103", "revision": 1, "status": "eligible", "domain": "II", "objectives": ["CAP-X Domain II"], "topic": "Success metrics for the analytics problem", "section": "Analytics Problem Framing", "difficulty": "moderate", "stem": "A credit team wants a model that 'improves collections.' After interviews, the operational decision is: which delinquent accounts a 12-person desk should call tomorrow. Which analytics success metric is most aligned?", "correct_key": "B", "options": [{"key": "A", "text": "Area under the ROC curve on a random 30% holdout of all accounts.", "is_correct": false, "rationale": "AUC on a random split ignores capacity (12 people) and the tomorrow decision. Ranking quality is not the business action.", "citations": [{"source": "CAP-Expert Domain II and V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Metrics must reflect the decision, not only discrimination"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Evaluating models against the decision"}]}, {"key": "B", "text": "Dollars collected from the 12 \u00d7 next-day call list versus the current ranking policy, on a time-aware test set.", "is_correct": true, "rationale": "The metric is the value of the actual decision under the real capacity constraint, evaluated without leakage from the future.", "citations": [{"source": "CAP-Expert Domain II", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Define analytics success in decision terms"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Business evaluation of model output"}]}, {"key": "C", "text": "Training-set accuracy of a 50% probability cutoff.", "is_correct": false, "rationale": "Training accuracy is optimistic and a default cutoff ignores desk capacity and dollars at risk.", "citations": [{"source": "CAP-Expert Domain V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Do not treat training fit as success"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Overfitting and improper metrics"}]}, {"key": "D", "text": "Number of features the model uses, minimized for interpretability.", "is_correct": false, "rationale": "Parsimony can be a constraint, not the objective. Fewer features does not mean better collections.", "citations": [{"source": "CAP-Expert Domain II", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Objectives vs constraints"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Interpretability as a design constraint"}]}]}, {"question_id": "CAPX-D3-Q101", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X Domain III"], "topic": "Data needed versus data available", "section": "Data", "difficulty": "moderate", "stem": "A hospital length-of-stay model needs admission hour, care-pathway, and discharge disposition. Admission hour is reliably captured. Pathway is in free-text notes. Disposition is missing for 40% of stays from one campus. What is the best next data action?", "correct_key": "C", "options": [{"key": "A", "text": "Drop the campus with missing disposition so the remaining table is complete.", "is_correct": false, "rationale": "Dropping a campus silently changes the population and can hide a site-specific process the model is supposed to support.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Document data limitations and population coverage"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Missingness and selection"}]}, {"key": "B", "text": "Impute every missing disposition with the system-wide mode and proceed to modeling.", "is_correct": false, "rationale": "Mode imputation on a campus-structured 40% hole invents a clinical event and conceals a data-generation problem.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Manipulate data so it is usable \u2014 without fabricating the target process"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Missing data handling"}]}, {"key": "C", "text": "Profile the missingness with campus operations, decide whether disposition can be recovered or must become a documented limitation, and only then choose an analysis population.", "is_correct": true, "rationale": "Domain III is identify, assess, and document. Missingness that is structural must be understood with data owners before transformation or exclusion.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Identify needed vs available data and document gaps"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Data quality and documentation"}]}, {"key": "D", "text": "Replace pathway notes and disposition with a purchased socioeconomic overlay because it is complete.", "is_correct": false, "rationale": "External completeness does not substitute for the clinical fields the decision needs. Convenience data is not fitness for use.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Fitness for the analytics problem, not mere completeness"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Relevant data vs available data"}]}]}, {"question_id": "CAPX-D3-Q102", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X Domain III"], "topic": "Leakage and time validity", "section": "Data", "difficulty": "advanced", "stem": "A churn model will be scored on Friday for customers who might cancel next month. A proposed feature is 'total tickets closed in the next 30 days.' What is the correct treatment?", "correct_key": "A", "options": [{"key": "A", "text": "Exclude it. At score time those tickets have not happened; using them is leakage and the model cannot be deployed as designed.", "is_correct": true, "rationale": "Features must be available at decision time. Future tickets are information the Friday job will not have.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Data must be usable for the decision timing"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Temporal validity of features"}]}, {"key": "B", "text": "Keep it; any variable that raises AUC in cross-validation is admissible.", "is_correct": false, "rationale": "Cross-validation can reward leakage. Deployability, not peak AUC, governs feature eligibility.", "citations": [{"source": "CAP-Expert Domain V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Evaluation must reflect deployment conditions"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Honest validation"}]}, {"key": "C", "text": "Keep it in training but drop it only if production monitoring shows drift.", "is_correct": false, "rationale": "The defect is logical, not a later drift issue. The feature is undefined at score time.", "citations": [{"source": "CAP-Expert Domain VII", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Monitoring does not excuse an invalid feature"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Lifecycle cannot repair leakage"}]}, {"key": "D", "text": "Replace ticket counts with the customer's account number because identifiers are safer.", "is_correct": false, "rationale": "An identifier is not a substitute feature and can introduce other leakage or fairness problems.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Choose data that represents the process, not an ID"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Appropriate attributes"}]}]}, {"question_id": "CAPX-D3-Q103", "revision": 1, "status": "eligible", "domain": "III", "objectives": ["CAP-X Domain III"], "topic": "Documentation and lineage", "section": "Data", "difficulty": "moderate", "stem": "Two analysts produce different monthly revenue totals from 'the same warehouse table.' Leadership asks which number is official. What documentation closes the gap fastest?", "correct_key": "B", "options": [{"key": "A", "text": "A slide with both totals and a request to 'use the average.'", "is_correct": false, "rationale": "Averaging unexplained extracts creates a third unofficial number and no lineage.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Required documentation and reporting"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Data documentation"}]}, {"key": "B", "text": "A data dictionary plus extract logic: grain, filters, as-of timestamp, inclusion of returns/tax, and the job that built each extract.", "is_correct": true, "rationale": "Domain III expects documentation that makes a number reconstructable: definition, timing, transformation, and owner.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Documentation and reporting needs"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Lineage and definitions"}]}, {"key": "C", "text": "The machine-learning code that later consumes the table.", "is_correct": false, "rationale": "Model code does not define the business extract. The conflict is upstream of modeling.", "citations": [{"source": "CAP-Expert Domain V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Model code \u2260 data definition"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Separate data prep documentation"}]}, {"key": "D", "text": "An email from the warehouse vendor confirming uptime was 99.9%.", "is_correct": false, "rationale": "Infrastructure availability does not reconcile two different business rules.", "citations": [{"source": "CAP-Expert Domain III", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Quality of definition, not only system uptime"}, {"source": "CH3 Analytics team PDF", "url": "https://drive.google.com/file/d/1AAad156Wsd8KdrscDpzxkyJSZ4zDvhC9/view", "locator": "Data quality dimensions"}]}]}, {"question_id": "CAPX-D4-Q101", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X Domain IV"], "topic": "Matching method to problem type", "section": "Methodology Selection", "difficulty": "moderate", "stem": "The decision is: set next week's production quantity for 200 SKUs to meet uncertain demand at minimum expected cost plus shortage penalty, with known capacities. Which approach is the best first selection?", "correct_key": "C", "options": [{"key": "A", "text": "k-means clustering of SKUs by color and brand.", "is_correct": false, "rationale": "Clustering does not produce a feasible production quantity under capacity and cost.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Select methods that can answer the framed problem"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Matching methods to problem type"}]}, {"key": "B", "text": "A deep neural net trained to classify whether a SKU is 'hot' or 'not.'", "is_correct": false, "rationale": "A binary label is not a production plan and ignores capacity and shortage cost.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Tools must enable the solution, not merely classify"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Predictive vs prescriptive"}]}, {"key": "C", "text": "A prescriptive inventory/production model (newsvendor or stochastic program) that uses a demand distribution and explicit capacities and costs.", "is_correct": true, "rationale": "The framed problem is a resource decision under uncertainty with costs and constraints \u2014 a prescriptive model is the matching family.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Select methods, techniques, and tools for the problem"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Prescriptive analytics under uncertainty"}]}, {"key": "D", "text": "A word cloud of customer reviews about the 200 SKUs.", "is_correct": false, "rationale": "Unstructured visualization does not yield a feasible weekly quantity.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Method must be capable of the required output"}, {"source": "CH4 The data PDF", "url": "https://drive.google.com/file/d/1EJ0ItOQSJ821dy9bZl8ERiAb-X9M6-Sq/view", "locator": "Descriptive methods and their limits"}]}]}, {"question_id": "CAPX-D4-Q102", "revision": 1, "status": "eligible", "domain": "IV", "objectives": ["CAP-X Domain IV"], "topic": "Tool and software choice", "section": "Methodology Selection", "difficulty": "moderate", "stem": "A regulated insurer must produce an explainable rate-change recommendation that internal actuaries can reproduce after staff turnover. A vendor demo shows a black-box model with slightly higher validation lift. What should guide the selection?", "correct_key": "D", "options": [{"key": "A", "text": "Always choose the higher-lift vendor model; lift is the only CAP-relevant criterion.", "is_correct": false, "rationale": "Domain IV includes constraints: explainability, reproducibility, skills, and governance \u2014 not lift alone.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Software and tools that enable the solution under constraints"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Practical constraints on method choice"}]}, {"key": "B", "text": "Choose spreadsheets only, because they are inherently auditable.", "is_correct": false, "rationale": "Spreadsheets can be opaque and fragile. Auditability comes from documented logic and control, not from the file type.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Tools must support control and reproduction"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Lifecycle and maintainability"}]}, {"key": "C", "text": "Postpone selection until a tool is found that needs no human actuary.", "is_correct": false, "rationale": "Staff-out-of-the-loop is not a stated requirement and conflicts with regulated review.", "citations": [{"source": "CAP-Expert Domain VI", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Deployment includes the operating model and people"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "People in deployment"}]}, {"key": "D", "text": "Prefer a method and toolchain actuaries can explain, reproduce, and maintain, even if lift is slightly lower, and record the lift trade-off for the sponsor.", "is_correct": true, "rationale": "Method selection is multi-criteria: decision quality, constraints, skills, and lifecycle. Transparency and reproducibility are binding here.", "citations": [{"source": "CAP-Expert Domain IV", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Select methods and tools that the organization can run"}, {"source": "CH5 Solution methodologies PDF", "url": "https://drive.google.com/file/d/1yyHXRUacIUJdwY3fbykUB-e_DtAAlezt/view", "locator": "Methodology selection under organizational constraints"}]}]}, {"question_id": "CAPX-D5-Q101", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X Domain V"], "topic": "Calibration and communicating findings", "section": "Model Development", "difficulty": "moderate", "stem": "A risk model\u2019s predicted 10% default band experiences 22% defaults in a recent out-of-time slice. Business users treat 10% as a pricing input. What is the most appropriate development action?", "correct_key": "B", "options": [{"key": "A", "text": "Ship the model; ranking quality (AUC) is still acceptable.", "is_correct": false, "rationale": "If users consume probabilities as prices, miscalibration is a business defect even when rank-order is fine.", "citations": [{"source": "CAP-Expert Domain V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Calibrate and communicate model findings"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Calibration vs discrimination"}]}, {"key": "B", "text": "Investigate the shift, recalibrate or rebuild so reported probabilities match observed rates on a time-respecting test, and show users the before/after reliability plot.", "is_correct": true, "rationale": "Domain V includes calibration and communication. Users acting on 10% need a probability that means 10% under current conditions.", "citations": [{"source": "CAP-Expert Domain V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Identify, calibrate, and communicate findings"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Model assessment and communication"}]}, {"key": "C", "text": "Multiply every score by 2.2 in production without analysis.", "is_correct": false, "rationale": "A global fudge factor without diagnosing mix shift or population change is not calibration discipline.", "citations": [{"source": "CAP-Expert Domain V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Calibration is an analyzed step, not a patch"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Responsible adjustment"}]}, {"key": "D", "text": "Convert the model to a pass/fail flag so probabilities are no longer shown.", "is_correct": false, "rationale": "Hiding the number does not fix a model the process still uses for pricing unless the decision itself changes.", "citations": [{"source": "CAP-Expert Domain II", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Output type must still match the decision"}, {"source": "CH2 Getting started PDF", "url": "https://drive.google.com/file/d/1W1eIPDgroLTY9bZJ3N0O3_3V5LHkhxT2/view", "locator": "Analytics outputs"}]}]}, {"question_id": "CAPX-D5-Q102", "revision": 1, "status": "eligible", "domain": "V", "objectives": ["CAP-X Domain V"], "topic": "Validation design", "section": "Model Development", "difficulty": "advanced", "stem": "A demand model will be retrained monthly and used to order parts with a six-week lead time. Which validation design best matches that use?", "correct_key": "A", "options": [{"key": "A", "text": "Walk-forward (rolling origin) evaluation at the monthly cadence, scoring a six-week horizon each fold, with error reported in units and dollars.", "is_correct": true, "rationale": "Validation must mimic retrain frequency and the lead-time horizon the order decision actually faces.", "citations": [{"source": "CAP-Expert Domain V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Build and evaluate the model under intended use"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Time-series / operational validation"}]}, {"key": "B", "text": "A single random 80/20 split of weeks, shuffled.", "is_correct": false, "rationale": "Shuffling weeks leaks future patterns into training and ignores lead time.", "citations": [{"source": "CAP-Expert Domain III and V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Respect time in data and evaluation"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Invalid splits"}]}, {"key": "C", "text": "Optimize only in-sample R\u00b2 and stop.", "is_correct": false, "rationale": "In-sample fit is not evidence the monthly six-week order will work.", "citations": [{"source": "CAP-Expert Domain V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Evaluation against intended use"}, {"source": "CH6 Modeling PDF", "url": "https://drive.google.com/file/d/1YLpRg9RUE-tha3Jkxu8U2qFRXCD07Gew/view", "locator": "Overfitting"}]}, {"key": "D", "text": "Ask the vendor for a marketing case study from another industry.", "is_correct": false, "rationale": "External anecdotes are not a validation design for this series, horizon, or cost structure.", "citations": [{"source": "CAP-Expert Domain V", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Findings must be produced for this model"}, {"source": "Exam resources", "url": "https://www.certifiedanalytics.org/exam-resources", "locator": "Blueprint: model development tasks"}]}]}, {"question_id": "CAPX-D6-Q101", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X Domain VI"], "topic": "Deployment into the business process", "section": "Deployment", "difficulty": "moderate", "stem": "A well-validated staffing model sits in a data-science repository. Frontline supervisors still build the weekly roster in a spreadsheet and have never seen the model output. What is the deployment gap?", "correct_key": "C", "options": [{"key": "A", "text": "There is no gap; repository storage is deployment.", "is_correct": false, "rationale": "Deployment means the solution is in the business process that makes the decision, not merely in a code repo.", "citations": [{"source": "CAP-Expert Domain VI", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Deliver the analytics solution into the business"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Deployment vs development"}]}, {"key": "B", "text": "The only gap is that AUC is not printed on the roster.", "is_correct": false, "rationale": "A model-quality statistic on a report does not put recommendations into the roster workflow.", "citations": [{"source": "CAP-Expert Domain VI", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Integration with the operating process"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Use of results"}]}, {"key": "C", "text": "The model is not embedded in the roster workflow with owners, timing, fallback, and training for supervisors.", "is_correct": true, "rationale": "Domain VI is delivery into the business: process, people, timing, and exception paths \u2014 not just an artifact.", "citations": [{"source": "CAP-Expert Domain VI", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Delivering the solution into the business"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Organizational deployment"}]}, {"key": "D", "text": "Deployment is complete once Legal has approved the algorithm in principle.", "is_correct": false, "rationale": "Legal review can be necessary but is not the same as operational use.", "citations": [{"source": "CAP-Expert Domain VI", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Operational delivery, not only approval"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Go-live conditions"}]}]}, {"question_id": "CAPX-D6-Q102", "revision": 1, "status": "eligible", "domain": "VI", "objectives": ["CAP-X Domain VI"], "topic": "Change management and fallback", "section": "Deployment", "difficulty": "advanced", "stem": "On go-live week the scoring job fails at 4 a.m. and cannot be rerun before the 6 a.m. dispatch cutoff. What deployment design should already exist?", "correct_key": "A", "options": [{"key": "A", "text": "A documented fallback (last good plan, rules, or manual protocol), an owner on call, and a communication path to dispatch.", "is_correct": true, "rationale": "Deployment includes failure modes. A cutoff-driven process needs a rehearsed degraded mode, not heroics.", "citations": [{"source": "CAP-Expert Domain VI", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Deliver a runnable business process, including exceptions"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Operational readiness"}]}, {"key": "B", "text": "An email to the data-science team after dispatch ends, asking them to look Monday.", "is_correct": false, "rationale": "After-the-fact notice does not protect the 6 a.m. decision.", "citations": [{"source": "CAP-Expert Domain VI", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Timing of the solution in the business calendar"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Service levels"}]}, {"key": "C", "text": "A plan to retrain the model from scratch during the outage.", "is_correct": false, "rationale": "Retraining is not an incident fallback and will miss the cutoff.", "citations": [{"source": "CAP-Expert Domain V vs VI", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Retrain is development; dispatch is operations"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Run vs rebuild"}]}, {"key": "D", "text": "Silence; failed jobs should not influence humans.", "is_correct": false, "rationale": "The business still dispatches. No output is itself a process failure that needs a designed response.", "citations": [{"source": "CAP-Expert Domain VI", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "The business process continues and must be designed for"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Exception handling"}]}]}, {"question_id": "CAPX-D7-Q101", "revision": 1, "status": "eligible", "domain": "VII", "objectives": ["CAP-X Domain VII"], "topic": "Lifecycle monitoring and retraining", "section": "Lifecycle Management", "difficulty": "moderate", "stem": "Six months after deployment, a pricing model's average predicted conversion is unchanged, but actual conversion in one channel has dropped by half. What is the most appropriate lifecycle action?", "correct_key": "C", "options": [{"key": "A", "text": "Do nothing; predicted conversion is stable so the model is healthy.", "is_correct": false, "rationale": "Stability of the prediction is not stability of the world. Outcome drift with flat predictions is a monitoring alert.", "citations": [{"source": "CAP-Expert Domain VII", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Ongoing oversight and calibration"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Performance monitoring"}]}, {"key": "B", "text": "Retrain immediately on all historical data including the broken channel without diagnosis.", "is_correct": false, "rationale": "Blind retrain can bake a broken process into the model. Diagnose first (process change, tracking bug, mix shift).", "citations": [{"source": "CAP-Expert Domain VII", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Oversight before recalibration"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "When to retrain"}]}, {"key": "C", "text": "Raise a monitoring incident: compare feature and outcome drift by channel, check logging and process changes, then recalibrate, retrain, or retire the channel policy with an owner.", "is_correct": true, "rationale": "Lifecycle management is detect, diagnose, act, and assign ownership \u2014 not a single reflex.", "citations": [{"source": "CAP-Expert Domain VII", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Oversight, calibration, and training over the life of the solution"}, {"source": "CH8 Deployment and life cycle PDF", "url": "https://drive.google.com/file/d/13v4WCaewlo67GWw0uyajVfCm7Nk2BmhG/view", "locator": "Model life cycle management"}]}, {"key": "D", "text": "Delete the monitoring dashboard so leadership is not alarmed.", "is_correct": false, "rationale": "Hiding drift is the opposite of lifecycle control.", "citations": [{"source": "CAP-Expert Domain VII", "url": "https://www.certifiedanalytics.org/cap-expert", "locator": "Ongoing oversight"}, {"source": "Exam resources", "url": "https://www.certifiedanalytics.org/exam-resources", "locator": "Lifecycle domain weight and intent"}]}]}]};
